insert into public.questions (question_id,paper_id,question_number,question_type,question_text,option_a,option_b,option_c,option_d,subject_primary,subsubject_primary,subject_secondary,chapter,topic_primary,topic_secondary,law_refs,tags,source_page_start,source_page_end,extraction_status,review_status,notes,is_published) values
('112-2301-041','112-2301',41,'single_choice','下列何者為行政主體？','中央研究院','國家通訊傳播委員會','國家教育研究院','國家資通安全研究院','行政法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],6,6,'parsed','pending_manual_review',null,true),
('112-2301-042','112-2301',42,'single_choice','下列何者非屬行政事實行為？','行政執行機關依行政執行法規定，對於營業場所斷水、斷電之「直接強制」','中央衛生主管機關發布新聞稿，警告人民吸菸有害健康','金融監督管理機關於職權範圍內，促請金融機構應遵循內部控制及委外作業管理','主管機關認定轄區內一特定土地為具公用地役關係之既成道路','行政法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],6,6,'parsed','pending_manual_review',null,true),
('112-2301-043','112-2301',43,'single_choice','下列何種執行之概念範圍最廣？','下命處分之執行力','行政執行法中對於公法上金錢給付義務之執行','行政訴訟法上之停止執行','行政執行法中對於行為義務之執行','行政法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],6,6,'parsed','pending_manual_review',null,true),
('112-2301-044','112-2301',44,'single_choice','乙駕駛漁船出海作業，從事違法行為，經主管機關依法對其作成裁處罰鍰並沒入漁船之處分。行政處 分確定後，主管機關以該處分為執行名義，實施強制執行，於執行程序中甲主張其為該漁船之所有權 人。如甲欲排除該執行名義，應如何提起救濟？','依行政訴訟法相關規定，向管轄行政法院提起債務人異議之訴','依行政執行法準用強制執行法相關規定，向普通法院提起第三人異議之訴','依行政執行法相關規定，本於利害關係人之地位向執行機關主張義務之履行經證明為不可能，申請 終止執行','依行政執行法相關規定，本於利害關係人之地位向執行機關主張執行命令侵害其利益，聲明異議','行政法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],6,6,'parsed','pending_manual_review',null,true),
('112-2301-045','112-2301',45,'single_choice','有關行政程序法之聽證程序，下列敘述何者錯誤？','行政機關僅於法律有明文規定時，始負舉行聽證之義務','有關設置重大公共設施行政計畫之確定，必須經聽證程序','行政機關為訂定法規命令舉行聽證時，應於政府公報或新聞紙公告','當事人不服經聽證程序作成之行政處分，得逕行提起行政訴訟','行政法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],6,6,'parsed','pending_manual_review',null,true),
('112-2301-046','112-2301',46,'single_choice','有關行政程序法第128 條及第129 條重新進行行政程序，下列敘述何者錯誤？','重新進行行政程序之決定可分為兩個階段，第一階段為是否重新進行之准駁，第二階段為重新進行 後所為之第二次裁決','申請人得以發現行政處分作成後始存在或成立之新證據為由申請重新進行，但限於經斟酌可受較有 利益之處分者為限','行政機關就重新進行行政程序所為之決定，性質上均非行政處分，受不利影響之申請人不得對之提 起行政爭訟','行政處分確定後，因事實變更而受不利影響之人，如非原處分之相對人或利害關係人，不得申請重 新進行行政程序','行政法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],6,6,'parsed','pending_manual_review',null,true),
('112-2301-047','112-2301',47,'single_choice','依政府資訊公開法規定，下列何者非屬政府機關應主動公開之資訊？','經濟部對民間企業之補助金額','憲法法庭審議案件之表決經過','勞動部勞務採購案之書面契約','立法院法制局委託學者進行之研究報告','行政法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],6,6,'parsed','pending_manual_review',null,true),
('112-2301-048','112-2301',48,'single_choice','下列何者非屬訴願程序或相當於訴願之程序？','不服經濟部之處分，向行政院提起之訴願','不服公務人員保障暨培訓委員會之處分，向考試院提起之訴願','不服律師懲戒委員會之懲戒決議，向律師懲戒覆審委員會提起之覆審','不服會計師懲戒委員會之懲戒決議，向會計師懲戒覆審委員會提起之覆審','行政法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],7,7,'parsed','pending_manual_review',null,true),
('112-2301-049','112-2301',49,'single_choice','下列行政訴訟事件，何者應適用通常訴訟程序？','因不服行政機關所為新臺幣2 萬元罰鍰及公布公司負責人姓名之處分提起撤銷訴訟','因不服行政機關所為新臺幣40 萬元罰鍰及環境講習8 小時之處分提起撤銷訴訟','因不服行政機關所為輔導教育處分提起撤銷訴訟','關於內政部移民署之行政收容事件涉訟','行政法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],7,7,'parsed','pending_manual_review',null,true),
('112-2301-050','112-2301',50,'single_choice','甲經營工廠，周轉困難，向主管機關申請紓困貸款遭拒；甲不服，擬提起行政爭訟，以謀救濟。如甲 另又憂心爭訟過久，自己工廠勢必不支倒閉時，應聲請下列何種類型之暫時權利保護，請求法院命主 管機關暫先提供紓困貸款？','假扣押','假處分','假執行','停止執行','行政法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],7,7,'parsed','pending_manual_review',null,true),
('112-2301-051','112-2301',51,'single_choice','依法律規定及司法院解釋意旨，有關行政訴訟審判權之敘述，下列何者錯誤？','甲以其所有之土地遭乙地方政府在其上鋪設柏油道路侵害其所有權為由，欲依結果除去請求權請求 乙回復原狀，應向行政法院提起訴訟','甲以其所有之土地遭乙地方政府在其上鋪設柏油道路侵害其所有權為由，欲依民法第767 條物上請 求權請求乙除去柏油並返還土地，應向普通法院提起民事訴訟','甲經經濟部依公司法第27 條規定指派為臺灣自來水股份有限公司董事，嗣因故遭撤換，甲如不服， 應循序提起行政訴訟','甲為前臺灣省自來水股份有限公司依行為時「臺灣地區省（市）營事業機構人員遴用暫行辦法」遴 用之人員，向公司請求發給資遣費遭拒，應向行政法院提起訴訟','行政法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],7,7,'parsed','pending_manual_review',null,true),
('112-2301-052','112-2301',52,'single_choice','關於行政訴訟之確認訴訟，下列敘述何者正確？','得提起撤銷訴訟時，亦得同時提起確認公法上法律關係存在或不存在之訴','確認行政處分無效之訴訟，應於行政處分達到後2 個月不變期間內，逕行提起行政訴訟','撤銷訴訟進行中原處分已消滅者，於原告有即受確認判決之法律上利益時，行政法院得依職權逕行 確認該行政處分為違法','應提起撤銷訴訟，誤為提起確認行政處分無效之訴訟，其未經訴願程序者，行政法院應以裁定將該 事件移送於訴願管轄機關','行政法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],7,7,'parsed','pending_manual_review',null,true),
('112-2301-053','112-2301',53,'single_choice','甲赴主管機關申請工廠紓困補貼，因下列事件而起爭訟時，何者原則上應屬民事法院之審判權範圍？','主管機關以甲之資格不符，當場駁回其申請','甲因申請遭駁回，要求返還已繳納之申請費用而遭拒','甲於辦理申請時與機關承辦人員起口角，甲請求長官對該承辦人員予以懲處遭拒','甲離開機關時，於門口臺階不慎踩空而跌傷，因此向該機關請求損害賠償','行政法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],7,7,'parsed','pending_manual_review',null,true),
('112-2301-054','112-2301',54,'single_choice','甲在颱風天開車經過由A 機關管理之某橋時，因瞬間暴雨水流湍急沖垮該橋橋墩致該橋斷裂，甲隨 車跌落溪底而死亡。事後經調查證實，以當時瞬間水量，任何堅固的橋墩皆會被沖垮。如甲之家屬主 張A 機關因該橋設置或管理有欠缺，請求國家賠償。下列何者為A 機關得拒絕賠償且可成立之理由？','損害賠償只有被害人可以請求，而被害人甲已死亡','該橋非屬公共設施','該公共設施設置或管理並無欠缺','本案並無公務員故意或過失之不法行為','行政法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],7,7,'parsed','pending_manual_review',null,true),
('112-2301-055','112-2301',55,'single_choice','依司法院解釋意旨，下列何者非因當事人蒙受特別犧牲而依法予以補償的情形？','當事人非因故意或重大過失行為而導致羈押，嗣後無罪確定','當事人依藥事人員指示或藥物標示使用藥物而發生死亡、障礙或嚴重疾病','當事人之土地上蓋有他人所有之建物，該建物經主管機關登錄為歷史建築，致其所有權權能受限制','當事人所有之土地因屬既成道路成立公用地役關係而無法為通常使用','行政法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],8,8,'parsed','pending_manual_review',null,true),
('112-2301-056','112-2301',56,'single_choice','有關國際法上永久中立國，下列敘述何者正確？','國家得自行宣告為永久中立國而無須獲得他國承認','永久中立國必須承諾不參加軍事同盟','在遭受他國攻擊時，永久中立國不得使用武力加以自衛','永久中立國得提供其領土給他國作為軍事上的使用','國際公法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],8,8,'parsed','pending_manual_review',null,true),
('112-2301-057','112-2301',57,'single_choice','有關國際法上政府承認，下列敘述何者正確？','一國得以他國新政府應繼承舊政府之條約義務，作為加以承認之條件','國家有義務不得承認藉由武裝革命所成立之新政府','不被承認的政府，在事實上無法行使國家之權能','撤銷對他國政府之承認，即等同於撤銷對其國家之承認','國際公法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],8,8,'parsed','pending_manual_review',null,true),
('112-2301-058','112-2301',58,'single_choice','有關國際組織之地位與權能，下列敘述何者正確？','聯合國之總部位置，由聯合國秘書處選定','依1949 年國際法院之諮詢意見，聯合國對雇員所受職務上損害，有獨立求償之權能','國際組織違反國際法，會員國當然應負擔連帶責任','國際組織之權能，僅以章程所明定者為限','國際公法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],8,8,'parsed','pending_manual_review',null,true),
('112-2301-059','112-2301',59,'single_choice','有關國際法上人民自決權，下列敘述何者錯誤？','人民自決權屬於國際法所明文承認之人權','人民自決權在規範性質上屬於國際強行法','人民自決權僅得由殖民地和非自治領土之人民行使','國家有義務避免採取干涉或限制人民自決權行使之行為','國際公法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],8,8,'parsed','pending_manual_review',null,true),
('112-2301-060','112-2301',60,'single_choice','關於國際法對個人權利之保障，下列敘述何者錯誤？','依1951 年難民地位公約，除因國家安全或公共秩序理由外，締約國不得驅逐合法在其領土內之 難民','公民與政治權利國際公約與經濟社會文化權利國際公約，為保障個人權利之核心國際公約','條約與各國司法實務都已確立，從事普通犯罪之人不得主張為政治犯而不受引渡','日內瓦公約及其附加議定書保障平民與戰俘，在武裝衝突中應受人道之待遇','國際公法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],8,8,'parsed','pending_manual_review',null,true),
('112-2301-061','112-2301',61,'single_choice','依條約締結法，關於條約之締結，下列敘述何者錯誤？','具專門性、技術性之條約及協定，其簽訂應由各專司部會主辦，無須經外交部同意','主辦機關於條約草案內容獲致協議前，得就談判之方針、原則及可能爭議事項，適時向立法院說明 並向立法院相關委員會報告','雙邊條約經立法院決議修正者，應退回主辦機關與締約對方重新談判','條約或協定之約本，應同時以中文及締約對方之官方文字作成，各種文本同等作準為原則','國際公法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],8,8,'parsed','pending_manual_review',null,true),
('112-2301-062','112-2301',62,'single_choice','關於沿海國依聯合國海洋法公約對大陸礁層得主張之權利，下列敘述何者正確？','即使事實延伸超過200 浬，沿海國仍僅得主張不超過200 浬之大陸礁層權利','所有締約國主張之大陸礁層，均須經大陸礁層界限委員會審查核定後始生拘束力','沿海國向國際海床管理局繳付開發大陸礁層之費用，得選擇以金錢或實物方式繳納','內陸國因事實上沒有大陸礁層，所以無權享有或分配大陸礁層開發所獲取之惠益','國際公法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],8,8,'parsed','pending_manual_review',null,true),
('112-2301-063','112-2301',63,'single_choice','甲國占領乙國部分領土。甲國僅加入公民與政治權利國際公約（ICCPR），乙國則僅加入經濟社會文 化權利國際公約（ICESCR）。關於乙國被占領區內人民享有之兩公約權利保障，下列敘述何者正確？','被占領區人民僅受ICCPR 保障','被占領區人民僅受ICESCR 保障','被占領區人民同受ICCPR 及ICESCR 保障','被占領區人民不受ICCPR 或ICESCR 保障','國際公法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],9,9,'parsed','pending_manual_review',null,true),
('112-2301-064','112-2301',64,'single_choice','國際法院對國家間爭端之訴訟管轄權，須以當事國合意為基礎，下列敘述何者錯誤？','國際法院對爭端利益相關第三方國家無管轄權，不影響其訴訟管轄權之行使','爭端當事國得於爭端發生後，藉由特別協議接受國際法院管轄','就爭端法律問題，國際法院規約締約國得隨時聲明承認國際法院強制管轄','國際法院規約締約國就其接受國際法院強制管轄之聲明，不得附帶任何條件','國際公法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],9,9,'parsed','pending_manual_review',null,true),
('112-2301-065','112-2301',65,'single_choice','關於國際海洋法法庭，下列敘述何者正確？','法庭管轄權不包括國家以外的實體','法庭管轄權不包括聯合國海洋法公約以外其他協定所生之爭端','法庭得為防止嚴重損害海洋環境，規定具有拘束力之臨時措施','法庭得依職權裁定締約國應迅速釋放被扣留之船舶與船員，無待爭端方之提出','國際公法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],9,9,'parsed','pending_manual_review',null,true),
('112-2301-066','112-2301',66,'single_choice','我國人甲在英屬開曼群島設立A 公司，10 年後甲因病去世，其於A 公司之股份由甲之妻乙、子丙、 女丁繼承。乙以丁損及其在英屬開曼群島遺產即A 公司股東權利為由，經英屬開曼群島法院裁定許 可指定自己為限制性遺產管理人，並召開股東會解除丁之董事職位並指定丙為董事，丁則主張甲於A 公司之股東權利乃為乙、丙、丁三人公同共有之遺產，乙未經全體繼承人同意推派為公同共有遺產之 管理，竟單獨以甲遺產管理人身分自居，乙係侵害其繼承權而違法解任其在A 公司之董事職位，故繼 續以A 公司董事自居。A 公司遂向我國法院提起確認A 公司與丁間董事委任關係不存在之訴。下列 敘述何者正確？','我國法院應依我國法定性為法人內部事項，並依涉外民事法律適用法第13、14 條定應適用之法律','我國法院應依我國法定性為繼承，並依涉外民事法律適用法第58 條定應適用之法律','我國法院應依英屬開曼群島法定性為法人內部事項，並依涉外民事法律適用法第13、14 條定應適 用之法律','我國法院應依英屬開曼群島法定性為繼承，並依涉外民事法律適用法第58 條定應適用之法律','國際私法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],9,9,'parsed','pending_manual_review',null,true),
('112-2301-067','112-2301',67,'single_choice','A 國人甲男與其妻乙定居於B 國，並育有丙子和丁女。甲男由於經商之故在我國銀行有鉅額存款，為 避免身後子女爭產，故生前即以公證遺囑表示將其財產的二分之一留給丙子。數年後，甲男舉家遷居 並設住所於C 國，不料丙在C 國誤交損友，甲在對丙失望之餘，遂在C 國以自書遺囑之方式撤回先 前的遺囑，並於撤回遺囑不久後死亡。丙對於該遺囑撤回方式之有效性有所爭執，遂於我國提起訴訟。 有關該遺囑撤回之方式，我國法院應如何適用法律？','得選擇適用A 國法或C 國法','得選擇適用B 國法或我國法','得選擇適用B 國法或C 國法','得選擇適用A 國法或我國法','國際私法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],9,9,'parsed','pending_manual_review',null,true),
('112-2301-068','112-2301',68,'single_choice','A 國人甲到B 國旅行時，因手機電池壞掉，即在當地向經銷商乙購買C 國之丙公司所生產之電池一 顆，充電時卻因電池過熱而燃燒焚毀。甲在我國對丙提起訴訟，若不考慮國際管轄權之問題，我國法 院原則應依何國法作為判決之準據法？','我國法','A 國法','B 國法','C 國法','國際私法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],9,9,'parsed','pending_manual_review',null,true),
('112-2301-069','112-2301',69,'single_choice','甲、乙均具中華民國籍，結婚後即移居至美國加州舊金山市，並在當地工作，而後在美國生有一子丙。 丙在舊金山長大，直至22 歲始赴紐約市工作，並在當地生活，鮮少回加州家中。設丙30 歲那年在加 拿大安大略省死亡，在紐約市留下遺產。問關於丙之遺產繼承問題，我國法院應如何適用法律？','適用中華民國法','適用加州法','適用紐約州法','適用安大略省法','國際私法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],9,9,'parsed','pending_manual_review',null,true),
('112-2301-070','112-2301',70,'single_choice','甲與乙皆為A 國人，在B 國偶然相遇，相談甚歡，甲向乙提起古董出售事宜，乙對古董頗有研究， 甚感興趣，兩人便於B 國依照B 國法律所規定之方式締結X 古董之買賣契約，並相約回國後再履行 契約義務。兩人於旅遊結束後各自回國，但於履行契約義務時，對於契約發生爭執。若甲與乙締約時 約定以中華民國法律為契約實質之準據法時，下列敘述，何者錯誤？','關於契約行為之方式，依涉外民事法律適用法第16 條規定，原則上依該行為所應適用之法律，則 在具體適用上亦以中華民國法律為準據法，此一結果可使契約之實質要件與形式要件之準據法一致','甲與乙既已依當事人意思決定契約之準據法，則不論是契約之實質要件、形式要件或效力等問題， 皆僅能以中華民國法律為準據法','甲與乙締約時雖已約定，以中華民國法律為契約實質之準據法，然關於契約之方式，亦得依行為地 法律，即B 國法所定之方式為之','關於古董所有權之移轉，涉及物權行為，是否已完成有效之權利移轉行為，應依物之所在地之法律 為斷','國際私法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],10,10,'parsed','pending_manual_review',null,true),
('112-2301-071','112-2301',71,'single_choice','A 國人甲與我國人乙在B 國之電腦展上磋商並簽訂契約，契約中明定以A 國法為準據法。之後，因 乙遲延給付，甲遂解除契約，但因甲已經先付百分之三十貨款，故甲向我國法院起訴，訴請乙返還價 金。我國法院應依何國法律判斷甲之主張有無理由？','我國法，因為我國為乙不當得利之受領地','A 國法，因為買賣契約以A 國法為準據法','A 國法，因為A 國為損害發生地','由法院判定何國法為關係最切之法，而後依該法為準據法','國際私法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],10,10,'parsed','pending_manual_review',null,true),
('112-2301-072','112-2301',72,'single_choice','我國人甲出口電腦零件一批至A 國，委由美國人乙運送，該批貨物因乙未盡保管注意義務遺失，致甲 受有損失。丙為該批貨物之保險人，依保險契約給付甲保險金，並代位行使甲對於乙之損害賠償請求 權，此時丙對乙求償之權利，其準據法為何？','侵權行為的準據法','運送契約的準據法','保險契約的準據法','原債權債務關係的準據法','國際私法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],10,10,'parsed','pending_manual_review',null,true),
('112-2301-073','112-2301',73,'single_choice','A 國人甲男被公司派駐至我國工作，結識B 國人乙女，兩人同居於我國新竹市。一年後，乙女懷有甲 男之胎兒，但雙方並未結婚，甲男結束在臺的工作後返回A 國，每月甲男皆會透過銀行匯款支付乙女 生活費用並代為支付房屋租金。關於甲男此些行為是否構成認領該胎兒，應適用何國法律？','應適用A 國法','應適用B 國法','得選擇適用A 國法或B 國法','應適用關係最切之我國法','國際私法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],10,10,'parsed','pending_manual_review',null,true),
('112-2301-074','112-2301',74,'single_choice','A 國人甲男與我國人乙女結婚，婚後設立住所於B 國並生下一子丙，嗣後因工作關係舉家遷居我國並 設定住所於高雄。由於甲乙感情生變，乙遂在我國法院對甲提起離婚訴訟並合併請求由乙擔任未成年 子丙之親權人。下列敘述何者正確？','甲非我國籍，故我國法院對此離婚訴訟並無國際管轄','關於是否具備離婚之原因應依起訴時之共同住所地法，即我國法','關於離婚之效力應依夫之本國法，即A 國法','關於丙之親權應依其出生時之住所地法，即B 國法','國際私法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],10,10,'parsed','pending_manual_review',null,true),
('112-2301-075','112-2301',75,'single_choice','A 國人甲在韓國法院對住在該國之B 國人乙取得勝訴確定判決（以下稱「K 判決」），由於乙在韓國之 財產不足以執行，故甲持該K 判決至我國欲就乙在我國之財產進行強制執行。下列敘述何者錯誤？','由於K 判決於我國不得自動執行，甲須先向我國法院起訴請求以判決宣示許可其執行','因債務人乙於我國並無住所，故我國法院對甲所提之請求許可執行之訴無管轄權','宣示許可執行判決時，法院不得就K 判決為實質的再審查，原則上應以形式審查之方式為之','有關間接管轄之判斷標準，通說認為應與直接管轄相同','國際私法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],10,10,'parsed','pending_manual_review',null,true),
('112-3301-001','112-3301',1,'single_choice','甲為法律系大四學生，清明掃墓時遇到伯父乙，乙聽聞甲正努力準備國家考試，為鼓勵甲，便向甲表 示：「如果你今年通過司法官、律師考試，金榜題名、為家族爭光的話，我就送你一台A 牌汽車。」 乙之表示為何種性質之附款？','附停止條件','附解除條件','附始期','附終期','民法','財產法','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],1,1,'parsed','pending_manual_review',null,true),
('112-3301-002','112-3301',2,'single_choice','下列關於住所之敘述，何者錯誤？','依一定事實，足認以久住之意思，住於一定之地域者，即為設定其住所於該地','限制行為能力人得經其法定代理人之同意選定住所','夫妻之住所，由雙方共同協議','因特定行為選定居所者，關於其行為，視為住所','民法','財產法','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],1,1,'parsed','pending_manual_review',null,true),
('112-3301-003','112-3301',3,'single_choice','14 歲之甲因女友遭乙言語騷擾，心生不滿，乃於民國（下同）109 年12 月25 日毆打乙，致乙胸骨斷 裂合併肺部挫傷、氣血胸及脊椎斷裂，呈現植物人狀態，因而受監護宣告，並由丙、丁自110 年6 月 1 日起擔任監護人。丙、丁於111 年12 月30 日始知甲行為時為未成年人，其法定代理人為戊、己。 嗣後丙、丁乃於112 年2 月1 日，以乙之監護人身分代理乙，訴請甲及戊、己賠償損害。下列敘述， 何者錯誤？','甲雖為限制行為能力人，但行為時具有識別能力，故甲應依民法第184 條第1 項前段規定，對乙負 損害賠償責任','戊、己兩人為甲之法定代理人，因對甲之監督有疏懈，故戊、己應依民法第187 條第1 項規定，與 甲連帶負損害賠償責任','因乙已呈現植物人狀態，故為保護乙之利益，民法第197 條第1 項規定之損害賠償請求權之二年消 滅時效起算，應就法定代理人丙、丁決之，即應自丙、丁知有損害及賠償義務人時起算','乙對甲及戊、己之侵權行為賠償損害請求權已罹於消滅時效，故丙、丁代理起訴請求甲及戊、己賠 償為無理由','民法','財產法','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],1,1,'parsed','pending_manual_review',null,true),
('112-3301-004','112-3301',4,'single_choice','17 歲之甲因心智缺陷，致不能辨識其意思表示之效果，受監護宣告。乙與甲訂立贈與契約，將其所有 之A 地贈與於甲。關於贈與契約之效力，下列敘述，何者正確？','甲是純獲法律上利益，故有效','甲是無行為能力人，故得撤銷','甲是無行為能力人，故無效','甲是限制行為能力人，故效力未定','民法','財產法','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],1,1,'parsed','pending_manual_review',null,true),
('112-3301-005','112-3301',5,'single_choice','依民法規定，下列關於法人之敘述，何者錯誤？','法人如有數名董事時，法人內部事務之執行，原則上取決於全體董事過半數之同意','董事因執行職務所加損害於他人時，法人與該行為人連帶負賠償責任','法人應設監察人，監察法人事務之執行','監察人有數人時，各監察人均得單獨行使監察權','民法','財產法','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],1,1,'parsed','pending_manual_review',null,true),
('112-3301-006','112-3301',6,'single_choice','甲有A 地，欲以新臺幣（下同）5,000 萬元賣出；乙欲以4,000 萬元買進。雙方討價還價之過程中， 甲突然寫信給乙，同意以400 萬元成交。乙明知這是甲之筆誤，並理解甲之真意是同意以4,000 萬元 成交。下列敘述，何者正確？','甲之筆誤是表示行為錯誤，得撤銷錯誤之意思表示','乙理解甲之真意，誤載無傷真意，以4,000 萬元成交','甲與乙二人並未互相表示意思一致，故契約不成立','甲與乙意思不一致時，應由法院依其事件之性質定之','民法','財產法','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],1,1,'parsed','pending_manual_review',null,true),
('112-3301-007','112-3301',7,'single_choice','甲使用詐術欺騙乙，讓乙陷於錯誤後，乙與丙訂立買賣契約。下列敘述，何者正確？','丙明知乙被詐欺或可得而知時，乙始得撤銷意思表示','不論丙是否明知被詐欺事實或可得而知，乙均得向丙撤銷意思表示','乙因被甲詐欺而為意思表示，故應向甲撤銷意思表示','乙因被甲詐欺而為意思表示，不得向丙撤銷意思表示','民法','財產法','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],2,2,'parsed','pending_manual_review',null,true),
('112-3301-008','112-3301',8,'single_choice','甲與乙訂立買賣契約，將其所有之A 地出賣於乙，雙方約定實際交易價格為新臺幣（下同）1,000 萬 元，然為逃漏稅捐，在買賣契約書上記載為700 萬元。下列敘述，何者正確？','甲與乙通謀虛偽意思表示，整個買賣契約無效','依買賣契約書記載，在700 萬元範圍契約有效','買賣價金以實際交易價格為準，甲得向乙請求1,000 萬元','甲得依意思表示錯誤之規定，決定是否要撤銷','民法','財產法','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],2,2,'parsed','pending_manual_review',null,true),
('112-3301-009','112-3301',9,'single_choice','甲與乙訂立借名登記契約，將其所有之A 地登記在乙之名下；詎料乙未經甲之同意，竟與丙訂立買賣 契約，將A 地出賣於丙，並將A 地之所有權移轉登記在丙之名下。下列敘述，何者正確？','乙無權處分，丙善意時，始得善意取得A 地之所有權','乙有權處分，縱使丙是惡意，亦得取得A 地之所有權','甲是A 地之真正權利人，乙與丙訂立之買賣契約無效','基於惡意不受保護原則，如丙係惡意，買賣契約無效','民法','財產法','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],2,2,'parsed','pending_manual_review',null,true),
('112-3301-010','112-3301',10,'single_choice','甲將A 屋出租於乙，乙與其配偶丙居住於A 屋。若A 屋失火，下列敘述，何者錯誤？','如因乙之重大過失導致失火，乙對甲應負擔失火之賠償責任','若甲依侵權行為之規定請求乙負擔失火之損害賠償責任時，於乙有重大過失者，始得成立','關於承租人因重大過失導致失火而須負擔損害賠償責任之規定，當事人不得透過合意加重承租人之 責任','因丙之重大過失導致失火時，承租人乙應依民法第433 條規定，對出租人甲負損害賠償責任','民法','財產法','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],2,2,'parsed','pending_manual_review',null,true),
('112-3301-011','112-3301',11,'single_choice','甲以每月新臺幣8,000 元將一層公寓租給乙，雙方未簽書面契約也無收受押租金。乙因想減輕房租負 擔，將其中一間房間轉租於同事丙。下列敘述，何者正確？','甲乙間約定租期為5 年卻未以字據訂立之，違反民法規定。故租期應視為縮短為1 年，只是屆期可 以更新之','甲得知乙將一間房間轉租於丙，雖不同意，但無法僅以此為理由向乙主張終止租賃契約','甲乙間約定每個月第一天繳交房租。乙上個月沒有繳交房租，本月初一又未繳租金。因為已達連續 兩個月未繳租金，故甲得在隔天向乙催告請求5 日內給付租金，否則即得終止租賃契約','租賃物之地板，因年久失修而影響通行，乙得逕行終止租賃契約','民法','財產法','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],2,2,'parsed','pending_manual_review',null,true),
('112-3301-012','112-3301',12,'single_choice','甲向乙租屋，雙方口頭約定租金為每月新臺幣（下同）2 萬元，押租金4 萬元，為期6 個月。未料甲 搬入居住3 個月後，乙將房屋出賣，並移轉所有權於丙，且登記在案。下列敘述，何者正確？','不動產租賃契約為要式契約，甲乙契約無效','甲丙間無租賃契約關係，丙得向甲主張無權占有，請求搬遷，返還占有物','甲乙之租賃契約雖未以書面訂定，但甲仍得向丙主張租賃契約繼續存在','縱使乙未將押租金轉交於丙，甲返還房屋後，仍得向丙請求返還押租金','民法','財產法','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],2,2,'parsed','pending_manual_review',null,true),
('112-3301-013','112-3301',13,'single_choice','甲為電腦經銷商，出售一台電腦於乙，關於物之瑕疵擔保責任，下列敘述，何者錯誤？','物之瑕疵，原則上應於危險移轉時存在，若於危險移轉後始發生，出賣人不負責任','若甲故意不告知瑕疵，乙雖因重大過失而不知有物之瑕疵時，甲仍應負擔物之瑕疵擔保責任','甲非故意不告知瑕疵時，乙受領電腦後，即時檢查後發現物之瑕疵，卻未通知甲，甲仍應對乙負擔 物之瑕疵擔保責任','價值或效用之減少非關重要者，不得視為瑕疵','民法','財產法','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],2,2,'parsed','pending_manual_review',null,true),
('112-3301-014','112-3301',14,'single_choice','住在臺北之甲將其使用半年之筆電出賣於乙，約定價金新臺幣15,000 元。雙方約定3 日後由甲將該 筆電運送至乙在桃園之工作室。3 日後，甲指示員工丙將該筆電送至乙處，路途中因丙超速駕駛，發 生車禍導致該筆電滅失。下列敘述，何者錯誤？','乙仍得請求甲交付該筆電','甲得向丙請求侵害所有權之損害賠償','乙得對甲依民法第226 條規定請求因給付不能之損害賠償','丙為甲之債務履行輔助人','民法','財產法','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],3,3,'parsed','pending_manual_review',null,true),
('112-3301-015','112-3301',15,'single_choice','甲乙為好友，甲因公調職出國工作2 年，乙剛好正在找屋承租，於是甲將其所有之A 屋，借給好友乙 住，約定甲在國外期間無償借乙住，乙幫忙保管整理A 屋。後來甲於國外需錢孔急，將A 屋賣給丙， 丙取得A 屋所有權後，以存證信函要求乙於10 日內，馬上搬出，10 日後丙馬上訴請乙返還A 屋。下 列敘述，何者正確？','甲乙間之使用借貸契約為期2 年，對於A 屋受讓人丙仍繼續存在，丙不得要求乙搬出','乙之占有並非無權占有，丙不得請求乙返還A 屋占有','丙得對乙主張A 屋之所有物返還請求權','甲乙間之使用借貸雖訂有期限，但期限屆滿前，甲得隨時請求返還借用物','民法','財產法','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],3,3,'parsed','pending_manual_review',null,true),
('112-3301-016','112-3301',16,'single_choice','若當事人約定買賣價金逾期未清償，應按「每千元每日壹元計算」支付違約金。關於該違約金債權請 求權之消滅時效，下列敘述，何者正確？','15 年','5 年','2 年','6 個月','民法','財產法','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],3,3,'parsed','pending_manual_review',null,true),
('112-3301-017','112-3301',17,'single_choice','甲於乙大賣場看中A 型液晶電視展示品，向乙購買一部同型商品，乙則允諾於次日免費運送A 型商 品至甲之住所地。當晚，乙之倉庫管理員丙依賣場之聯絡，備妥A 型商品一部，並完整包裝置放於倉 庫內，等待次日一早即可將其交付運送人員運送於甲。詎料，當晚因倉管人員丁之過失致倉庫及其內 之商品（含A 型商品）燒燬殆盡。就受此影響之甲、乙間之法律關係，下列敘述，何者正確？','甲應催告乙再次交付A 型商品，並於催告未果後，始得解除契約','甲不得再向乙請求交付A 型商品，乙亦不得請求甲支付價金','甲不得再向乙請求交付A 型商品，僅得向乙請求賠償因此所受損害','甲得逕行解除與乙就A 型商品之買賣契約，並不得請求賠償因此所受損害','民法','財產法','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],3,3,'parsed','pending_manual_review',null,true),
('112-3301-018','112-3301',18,'single_choice','民法第191 條之1 規定，對於商品製造人責任之成立要件有三項推定。不包括下列何項推定？','推定商品有欠缺','推定商品製造人之過失','推定商品使用人有損害','推定商品之欠缺與損害間有因果關係','民法','財產法','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],3,3,'parsed','pending_manual_review',null,true),
('112-3301-019','112-3301',19,'single_choice','下列關於承攬契約與委任契約之敘述，何者正確？','承攬人、受任人原則上均應自己完成工作或處理委任事務，不得使第三人代為處理','承攬契約，於工作未完成前，僅定作人得隨時終止契約；委任契約，當事人之任何一方得隨時終止 契約','承攬契約及委任契約均因定作人或委任人破產而消滅','承攬契約必為有償之契約，委任契約必為無償之契約','民法','財產法','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],3,3,'parsed','pending_manual_review',null,true),
('112-3301-020','112-3301',20,'single_choice','甲乙丙丁戊共同對A 負有新臺幣（下同）100 萬元之連帶債務，未約定分擔部分，已屆清償期。在5 人當中，A 對於丙表示免除其債務，甲則是對A 有40 萬元已屆期之債權，而戊則是負債累累逃亡海 外不知去向，A 選擇向乙請求清償所有連帶債務。乙則是得知丙已被免除債務，並對A 以甲之債權主 張抵銷後，清償全部剩下債務。乙在清償全部債務後，對於其他四人行使求償權。其中，對於戊不知 去向無法求償之部分，則是以擴張求償權之方式，請求共同承擔。下列敘述，何者正確？','乙對A 應負有共同清償40 萬元之義務','A 已免除丙之債務，故乙不得對丙求償5 萬元','乙得向甲請求5 萬元','乙得向丁行使求償權，僅得請求20 萬元','民法','財產法','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],3,3,'parsed','pending_manual_review',null,true),
('112-3301-021','112-3301',21,'single_choice','甲因為平日相當繁忙，故與乙之間訂立概括委任契約協助處理事務，以減輕負擔。下列敘述，何者正確？','甲乙間既然訂立委任契約，所以必然同時發生事務處理權之授與，否則乙無法處理事務','委任契約可為有償契約，亦可為無償契約。故乙若受有報酬，處理委任事務時，除應依委任人之指 示，並應負與處理自己事務為同一之注意義務','雖然是概括委任，若乙要幫甲所有而空著未使用之房屋出租於丙，打算訂定為期3 年之租賃契約， 應得到甲之特別授權','甲乙於委任契約中，未特別約定應由乙親自處理事務時，乙得隨時委任丁代為處理事務','民法','財產法','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],4,4,'parsed','pending_manual_review',null,true),
('112-3301-022','112-3301',22,'single_choice','下列關於民法上合夥之敘述，何者錯誤？','合夥是雙務契約、有償契約','合夥具法人資格，有權利能力','對合夥負有債務者，不得因其對任何合夥人有債權而主張抵銷','合夥財產若不足清償合夥之債務時，各合夥人對於不足之額，應負連帶責任','民法','財產法','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],4,4,'parsed','pending_manual_review',null,true),
('112-3301-023','112-3301',23,'single_choice','甲缺錢，向乙表示想借款新臺幣（下同）500 萬元，乙回答沒問題，10 日後可匯款至甲銀行帳戶。雙 方約定借款利息之利率為週年22%，分10 年攤還，並於第5 年開始才可返還原本。而且，乙為了收 取更多利息，以預扣利息為由，實際上僅交付甲400 萬元。依民法規定，下列敘述，何者正確？','甲乙合意借貸金錢時，消費借貸契約已成立','該利息約定過高，超過部分雖非無效，但乙無請求權','甲欲提前攤還原本以降低負擔，於借款經過1 年後，即得隨時為之','預扣之100 萬元既未實際交付甲，並非貸與本金之一部分','民法','財產法','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],4,4,'parsed','pending_manual_review',null,true),
('112-3301-024','112-3301',24,'single_choice','甲對乙有新臺幣（下同）500 萬元之債權並已屆清償期，乙卻遲遲未為清償。因為乙近兩年來生意與 股票投資失敗，負債累累。甲經過詳查後，發現乙之財產僅剩對丙有400 萬元之債權。雖然對丙之債權 已過清償期甚久，但乙覺得反正要回錢，只會被眾債權人瓜分，所以怠於討回。下列敘述，何者錯誤？','甲若要行使代位權，應以自己名義行使乙之權利，且自己並無優先其他債權人受償之權利','甲原則上必須在乙已負給付遲延責任，始得對丙行使代位權。但如有中斷時效等保存乙債權所必要 之行為者，不在此限','乙對於丙之債權，必須比甲對乙之債權更早發生，否則甲無權行使代位權','此項代位權之行使，未必以訴為之','民法','財產法','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],4,4,'parsed','pending_manual_review',null,true),
('112-3301-025','112-3301',25,'single_choice','甲將其對乙之貨款債權讓與於丙，並通知乙。下列敘述，何者錯誤？','乙受通知時，乙原得對甲主張之同時履行抗辯權，仍得對丙主張','乙受通知時，乙原得對甲主張之消滅時效抗辯權，仍得對丙主張','乙受通知後，乙始具備得對甲主張抵銷之要件者，亦得對丙主張','乙受通知後，乙基於法定事由解除與甲之原契約時，乙得對丙拒絕給付系爭貨款','民法','財產法','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],4,4,'parsed','pending_manual_review',null,true),
('112-3301-026','112-3301',26,'single_choice','下列關於擔保物權之敘述，何者錯誤？','以著作財產權為質權之標的，除另有約定外，著作財產權人仍得行使其著作財產權','質權以記名股票為標的，依背書方法及交付證券於質權人者，即生設定質權之效力，無須於背書處 記載表示設質或其他同義文字','若銀行預先授予客戶未來兩年內商業信用貸款額度，並由客戶提供不動產設定最高限額抵押權，縱 客戶從未向銀行借款，該最高限額抵押權仍屬有效','最高限額抵押權在原債權確定前，若第三人為債務人清償債務者，最高限額抵押權亦隨同移轉於第 三人','民法','財產法','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],4,4,'parsed','pending_manual_review',null,true),
('112-3301-027','112-3301',27,'single_choice','甲為A 地所有人，A 地係空地，為擔保借款而設定普通抵押權於乙，嗣於抵押權人乙聲請法院拍賣A 地時，因A 地上有B 屋存在而致拍賣價格低落。下列有關抵押權存續中發生之情事，何者乙不得聲 請就該B 屋併付拍賣？','甲在A 地上建築B 屋，隨即將A 地與B 屋出賣並移轉所有權登記於丙','甲將A 地設定普通地上權於丙，丙則在A 地上建築B 屋，且乙依民法第866 條規定已由法院除去 該地上權者','無權占有人丙在A 地建築B 屋','甲將A 地轉賣並移轉所有權登記於丙，丙在A 地上建築B 屋','民法','財產法','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],4,4,'parsed','pending_manual_review',null,true),
('112-3301-028','112-3301',28,'single_choice','甲為A 屋之所有人。甲與乙訂立承攬契約，約定：乙承攬A 屋全部管線更新與重新裝潢，並提供承 攬工作所需之全部材料；甲應給付乙報酬新臺幣（下同）1,000 萬元。乙已完成承攬工作。下列敘述， 何者錯誤？','甲取得乙為完成承攬之工作，而施作於A 屋之全部材料之所有權','乙施作材料於A 屋之行為，乃加工','乙得請求甲給付1,000 萬元報酬','乙所供給材料之價額，推定為承攬報酬之一部','民法','財產法','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],5,5,'parsed','pending_manual_review',null,true),
('112-3301-029','112-3301',29,'single_choice','甲乃A 地所有人。A 地市價新臺幣（下同）2 億元。甲將A 地設定普通抵押權於乙，用以擔保對乙所 負1 億元借款債務，借款期間一年。甲與乙並約定：甲若屆期後一年內，未全部清償1 億元借款債務， 則由乙取得A 地所有權。這項約定並經登記在案。甲其後出賣A 地，並移轉A 地所有權登記於丙。 甲於屆期後之一年間僅返還借款5 千萬元於乙。下列敘述，何者正確？','乙得請求丙移轉抵押之A 地所有權於自己','乙得請求甲移轉抵押之A 地所有權於自己','乙得請求塗銷丙為A 地所有人之登記','乙得主張甲與丙間之A 地買賣無效','民法','財產法','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],5,5,'parsed','pending_manual_review',null,true),
('112-3301-030','112-3301',30,'single_choice','甲、乙、丙三人共有A 地，應有部分各為三分之一，甲、乙未經丙同意而將A 地贈與丁，丁明知A 地係三人共有且僅甲、乙表示贈與意思，卻仍表欣然接受，並完成所有權移轉登記。丙嗣後得知後表 示不同意此贈與。下列敘述，何者錯誤？','甲、乙與丁間關於A 地贈與契約有效成立','甲、乙移轉A 地所有權於丁之物權行為有效，丙不得依民法第767 條規定請求丁返還A 地','甲、乙移轉A 地所有權於丁之物權行為，因丙不同意而不生效力，丙得請求丁塗銷A 地所有權移 轉登記，並將之返還於全體共有人','丙於甲、乙贈與A 地於丁時，丙不得就甲、乙應有部分讓與主張優先承買權','民法','財產法','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],5,5,'parsed','pending_manual_review',null,true),
('112-3301-031','112-3301',31,'single_choice','甲女於民國112 年死亡，其夫乙、女兒丙、養子丁繼承A 地，乙與丙不顧丁反對，將A 地出賣並完 成所有權移轉登記於戊。下列敘述，何者正確？','乙之公同共有比例為二分之一，丙與丁之公同共有比例各為四分之一','A 地為公同共有，故有償處分A 地應得乙、丙、丁全體同意','乙、丙與戊間移轉A 地所有權之行為有效','丁不得主張優先承購','民法','財產法','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],5,5,'parsed','pending_manual_review',null,true),
('112-3301-032','112-3301',32,'single_choice','下列何者不屬非因法律行為，於登記前已取得不動產物權之情形？','典權人因出典人回贖之除斥期間屆滿，而取得典物所有權','自己出資興建未辦保存登記之建築物','債權受讓人於受讓債權時，隨同取得擔保該債權之普通抵押權','買受人取得法院命出賣人辦理房屋所有權移轉登記之確定判決','民法','財產法','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],5,5,'parsed','pending_manual_review',null,true),
('112-3301-033','112-3301',33,'single_choice','乙於盜取甲之A 車後，拆換車牌，將之置於販售二手車之丙商行寄賣。丙旋以自己之名義，出賣於善 意且非因重大過失而不知其事之丁，丁並受讓A 車之所有權。經過一年，甲發現A 車現為丁占有， 遂訴請丁回復交還A 車。對此，丁主張其已善意取得A 車所有權，又提出甲非償還其已支出之價金， 不得回復其物之抗辯。下列敘述，何者錯誤？','如甲償還丁所支出之價金，則甲自訴請丁回復A 車時起，其所有權之回復向將來發生效力','乙將甲之A 車置於丙商行寄賣，丙為A 車之直接占有人','雖丁得善意取得A 車所有權，但甲所行使之回復請求權，乃善意取得之例外規定','丁提出甲非償還其支出之價金，不得回復其物之抗辯，係屬有理','民法','財產法','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],5,5,'parsed','pending_manual_review',null,true),
('112-3301-034','112-3301',34,'single_choice','甲將其所有某公司發行之記名股票交付於乙，甲並於股票過戶申請書上之出讓人欄用印，交由乙對外 洽談讓售事宜。惟乙嗣後持該股票作為其向丙借款之擔保，乙、丙為設定讓與擔保之約定。丙基於上 開約定信賴乙有讓與該股票以供擔保之權利，而善意且無重大過失受讓該股票之占有。下列敘述，何 者正確？','甲將其股票交由乙對外洽談讓與事宜，乙係間接占有該股票','丙得善意取得該股票','乙、丙間關於讓與擔保之約定，因違反物權法定原則而無效','甲訴請丙返還該股票，係屬有理','民法','財產法','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],5,5,'parsed','pending_manual_review',null,true),
('112-3301-035','112-3301',35,'single_choice','甲乃A 帆船所有人。甲平日將A 帆船停放在港口。乙未經甲同意，將A 帆船駛離港口，並在近海遊 玩。乙出發駛離港口前，為保養A 帆船花費新臺幣（下同）1 萬元。乙駕駛A 帆船駛離港口之際，駕 駛粗心大意，A 帆船因此擦撞若干消波塊，船身受有若干擦痕，維修費用達10 萬元。下列敘述，何 者錯誤？','甲請求乙償還使用A 帆船之利益，有理由','乙依民法關於無因管理之規定，請求甲償還保養A 帆船之費用1 萬元，有理由','以乙因A 帆船受損而受有利益為限，甲請求乙賠償10 萬元，方有理由','甲得請求乙返還A 帆船','民法','財產法','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],6,6,'parsed','pending_manual_review',null,true),
('112-3301-036','112-3301',36,'single_choice','甲男乙女於民國（下同）111 年1 月10 日為書面之結婚約定，且有兩名證人簽名，並於次日至戶政事 務所辦妥結婚登記。然而，該結婚書約之兩名證人之一，僅聽聞甲單方轉述其與乙之結婚合意，並未 親自見聞乙結婚之真意。111 年3 月1 日乙發現自己懷孕，但甲早已離家出走、對乙不聞不問。乙於 111 年12 月20 日生下丙，甲完全不知情，且甲於111 年12 月31 日不幸車禍死亡。下列關於甲、乙、 丙間法律關係之敘述，何者錯誤？','丙依法為甲之婚生子女，無須認領','丙依法視為乙之婚生子女，無須認領','甲乙之婚姻自始無效','甲死亡後，乙並非甲之法定繼承人','民法','親屬繼承','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],6,6,'parsed','pending_manual_review',null,true),
('112-3301-037','112-3301',37,'single_choice','下列關於離婚後，對於未成年子女權利義務之行使或負擔之敘述，何者正確？','民法並未明文承認離婚後，父母得對於未成年子女共同行使權利、負擔義務','離婚後未行使子女親權之一方，原則上不負子女扶養義務','父母均不適合行使權利時，法院應選定第三人為子女之監護人，並命其父母負擔扶養費用','依協議或裁判決定由一方行使親權後，他方若能證明由自己行使將對子女更為有利，得請求法院改 定親權人','民法','親屬繼承','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],6,6,'parsed','pending_manual_review',null,true),
('112-3301-038','112-3301',38,'single_choice','關於非婚生子女之稱姓，下列敘述，何者錯誤？','非婚生子女從母姓，但經生父認領者應改從父姓','非婚生子女經生父認領後，始為出生登記，登記為父姓。於其未成年前，父母仍有機會以書面約定 變更為母姓','非婚生子女原本從母姓，於成年後始被生父認領。該成年子女得自行決定變更為父姓','非婚生子女於未成年時，經生父認領，父母已書面約定變更為父姓，該子女成年後，仍得自行決定 再次變更為母姓','民法','親屬繼承','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],6,6,'parsed','pending_manual_review',null,true),
('112-3301-039','112-3301',39,'single_choice','下列何者為無效婚姻？','甲乙離婚後，乙與甲之叔父丙結婚','甲之婚生子乙與甲之養女丙結婚','甲乙為夫妻，甲丙為兄弟。甲死亡後，乙與丙結婚','甲乙為兄弟，乙丙為夫妻，甲戊為養父子。甲於乙死亡後，終止與戊之收養關係。丙與戊結婚','民法','親屬繼承','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],6,6,'parsed','pending_manual_review',null,true),
('112-3301-040','112-3301',40,'single_choice','甲男與乙女結婚後，經過五年，乙女生下丙女。惟丙在血緣上並非甲之女，而是乙女與其婚外情對象 丁男所生。下列敘述，何者正確？','丁不待婚生否認之結果，即得認領丙為女兒，使其認祖歸宗，並得與乙商議丙之親權行使','甲得知乙出軌，遂憤而離家出走，行蹤不明十餘年，導致無人可否認丙為甲之女','丙於未成年時知悉其生父為丁，成年後二年內，得對甲提起否認推定生父之訴','乙於丙出生時即明知丙為丁之骨肉，但擔心與甲婚姻破裂，不敢張揚。甲在丙三歲時死亡，乙得提 起訴訟，否認甲、丙之親子關係','民法','親屬繼承','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],6,6,'parsed','pending_manual_review',null,true),
('112-3301-041','112-3301',41,'single_choice','甲男乙女於民國（下同）110 年結婚，未約定夫妻財產制。乙於結婚前有一子丙。甲有婚前財產新臺 幣（下同）200 萬元，乙有婚前財產500 萬元。112 年初，乙女因病死亡。乙死亡時，甲有財產1,200 萬元，乙有財產1,000 萬元。下列敘述，何者正確？','丙得對甲請求100 萬元之剩餘財產分配','丙得對甲請求200 萬元之剩餘財產分配','丙得對甲請求250 萬元之剩餘財產分配','丙無權利對甲主張剩餘財產分配','民法','親屬繼承','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],6,6,'parsed','pending_manual_review',null,true),
('112-3301-042','112-3301',42,'single_choice','甲男與乙女為男女朋友，乙自甲懷胎生下丙子，乙單身未婚。但甲已有配偶丁，故甲、乙始終未結婚。 下列敘述，何者錯誤？','甲知悉丙為自己骨肉，每月給付乙新臺幣6,000 元作為丙之扶養費用，但礙於丁之反對，並未至戶 政機關將丙認領登記為子女。甲死亡時，丙、丁均為甲之法定繼承人','甲從未給付丙之扶養費用，亦未曾為丙辦理認領登記。丙在乙單獨扶養下長大成人。甲眼見丙頗有 資產，欲認領丙，此際應得丙之同意','甲如未有撫育事實，且尚未辦理認領登記即死亡者，乙得向甲之繼承人丁提起認領子女之訴，請求 判決丙為甲之子女','甲不願認領丙，但在乙之脅迫下不得不辦理認領登記。甲事後不得主張被脅迫而撤銷認領之意思表示','民法','親屬繼承','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],7,7,'parsed','pending_manual_review',null,true),
('112-3301-043','112-3301',43,'single_choice','甲男、乙女婚後育有丙女。丙女8 歲時，自祖母獲贈A 房地。丙16 歲起就讀私立雙語高中，學費昂 貴，甲遂代理丙，向銀行辦理就學貸款，並將A 房地設定普通抵押權於銀行。甲之行為效力如何？','因父母為未成年人之法定代理人，故甲得單獨代理丙借款及設定抵押權，甲之行為有效','因丙滿16 歲，甲僅得同意丙之法律行為，不得直接代理丙為法律行為，故甲之行為不生效力','因父母須共同行使親權，乙並未與甲共同為之，甲為無權代理，其行為效力未定','因父母處分未成年子女之特有財產，須為子女之利益，甲之行為違反丙之利益，故為無效','民法','親屬繼承','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],7,7,'parsed','pending_manual_review',null,true),
('112-3301-044','112-3301',44,'single_choice','甲男與乙女結婚，甲尚有與前婚配偶所生之丙子共同生活。乙於懷胎丁子8 個月時，甲男意外去世， 丙此時已成年。甲死亡時，留下財產及債務。下列敘述，何者正確？','乙為丁之法定代理人，乙於丁出生後為遺產分割協議時，法院得依職權為丁選任特別代理人','丁因民法第7 條規定，關於個人利益視為既已出生，故不適用概括繼承之規定，僅繼承財產，無須 繼承債務','乙於丁出生後未開具財產清冊，而違法清償致生損害賠償責任，丙、丁為共同繼承人，亦應併同承 擔該清償責任','丙就甲之遺產清償其債務完畢後，請求分割遺產，但並未保留丁之應繼分，丁出生後，其分割雖有 效，但丙應對丁負損害賠償責任','民法','親屬繼承','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],7,7,'parsed','pending_manual_review',null,true),
('112-3301-045','112-3301',45,'single_choice','甲之父母早逝，有成年之子乙。乙有5 歲之子丁。戊喪妻有子庚。戊收養甲。經法院認可時，乙不同 意與戊發生祖孫關係。甲因車禍先於戊死亡。戊死亡時，何者為戊之遺產繼承人？','乙','庚','乙、庚','丁、庚','民法','親屬繼承','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],7,7,'parsed','pending_manual_review',null,true)
insert into public.questions (question_id,paper_id,question_number,question_type,question_text,option_a,option_b,option_c,option_d,subject_primary,subsubject_primary,subject_secondary,chapter,topic_primary,topic_secondary,law_refs,tags,source_page_start,source_page_end,extraction_status,review_status,notes,is_published) values
('112-3301-046','112-3301',46,'single_choice','單親母親甲有子女乙、丙、丁三人，其中乙育有一女戊，甲之老父己尚健在。甲死亡時，留下遺產新 臺幣120 萬元，並未留有遺囑。下列關於遺產繼承之敘述，何者錯誤？','若無喪失繼承權事由發生，則甲之遺產，乙、丙、丁各有三分之一之應繼分','若甲生前受乙之重大虐待侮辱者，乙當然喪失對甲之繼承權','若甲生前乙故意殺丙未遂但被判刑確定者，乙當然喪失對甲之繼承權','若甲生前原本擬撰寫遺囑，但乙以強暴脅迫手段不許甲為之，乙當然喪失對甲之繼承權','民法','親屬繼承','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],7,7,'parsed','pending_manual_review',null,true),
('112-3301-047','112-3301',47,'single_choice','附解除條件之遺囑，於遺囑人死亡前，該條件已成就者，該遺囑之效力為何？','遺囑效力未定','遺囑失效','遺囑撤回','遺囑意思表示之撤銷','民法','親屬繼承','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],7,7,'parsed','pending_manual_review',null,true),
('112-3301-048','112-3301',48,'single_choice','甲乙為夫妻，並育有丙丁兩子，甲死亡時，留有遺產新臺幣（下同）1,200 萬元。依據甲之遺囑內容， 遺產中900 萬元已遺贈給好友戊，乙丙丁則各得100 萬元。乙丙丁以甲之繼承人身分，各得向戊請求 多少錢？','乙100 萬元，丙100 萬元，丁100 萬元','乙150 萬元，丙150 萬元，丁150 萬元','乙200 萬元，丙200 萬元，丁200 萬元','乙250 萬元，丙250 萬元，丁250 萬元','民法','親屬繼承','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],7,7,'parsed','pending_manual_review',null,true),
('112-3301-049','112-3301',49,'single_choice','下列關於共同繼承之敘述，何者正確？','全體繼承人於遺產分割前為分別共有','共同繼承人僅以人數之過半數，即得處分其遺產','全體繼承人對於被繼承人之債務，不以因繼承所得遺產為限，負連帶責任','全體繼承人之遺產分割，自分割時，始發生效力，而不溯及於繼承開始時','民法','親屬繼承','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],7,7,'parsed','pending_manual_review',null,true),
('112-3301-050','112-3301',50,'single_choice','依民法規定，下列何者得為繼承之標的？','扶養費請求權','作曲義務','占有','回復名譽請求權','民法','親屬繼承','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],7,7,'parsed','pending_manual_review',null,true),
('112-3301-051','112-3301',51,'single_choice','關於民事訴訟上事實、證據之蒐集原則，下列敘述，何者正確？','當事人未主張之事實，法院一概不得加以斟酌','經當事人自認之事實，如法院認為違背真實，得不受其拘束','法院調查當事人所未聲明之證據，均屬違背法令','當事人所主張不利於己之事實，縱未經他造援用，法院亦得採為裁判基礎','民事訴訟法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],8,8,'parsed','pending_manual_review',null,true),
('112-3301-052','112-3301',52,'single_choice','關於民事訴訟之公開審理主義，下列敘述，何者正確？','小額程序之言詞辯論，原則上不公開審判','經兩造合意不公開審判者，法院即使認為不適當，仍不得行公開審判','當事人以涉及業務上秘密為由，聲請法院不公開審判者，法院即使認為聲請不適當，仍不得公開審判','若法院認為有妨害善良風俗情形，得職權決定不公開審判','民事訴訟法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],8,8,'parsed','pending_manual_review',null,true),
('112-3301-053','112-3301',53,'single_choice','關於訴訟之期間，下列敘述，何者錯誤？','原告起訴時未繳納裁判費，經審判長命原告於收受裁定後7 日內補繳裁判費，原告之住所如不在法 院轄區內，得扣除在途期間','法院以原告未遵期補繳裁判費，裁定駁回原告之訴，原告對該裁定提起抗告，如遲誤法定期間，其 抗告不合法','法定期間與裁定期間，如有重大理由，得伸長或縮短之','不可歸責於當事人或代理人之事由，致遲誤不變期間者，應透過回復原狀制度加以救濟','民事訴訟法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],8,8,'parsed','pending_manual_review',null,true),
('112-3301-054','112-3301',54,'single_choice','甲（住高雄市）與乙（住新竹市）訂立買賣契約，購買乙所有坐落在臺北市中正區的A 屋，並約定於 臺南市交付買賣價金。嗣甲並未依約交付價金，但已遷入A 屋居住使用，乙依買賣契約向臺灣高雄地 方法院起訴，請求甲給付買賣價金。關於管轄權，下列敘述，何者錯誤？','就請求給付買賣價金之訴，臺灣高雄地方法院有管轄權','若乙向臺灣臺南地方法院起訴請求甲給付買賣價金，甲抗辯該法院無管轄權，並無理由','於訴訟審理中，乙主張解除買賣契約，變更為依所有物返還請求權，請求甲返還A 屋，臺灣高雄地 方法院應以裁定將該事件移送臺灣臺北地方法院','於訴訟審理中，甲依買賣契約反訴請求乙移轉A 屋所有權，僅臺灣臺北地方法院有管轄權','民事訴訟法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],8,8,'parsed','pending_manual_review',null,true),
('112-3301-055','112-3301',55,'single_choice','關於濫訴禁止之規定，下列敘述，何者正確？','起訴基於惡意、不當目的或有重大過失，且事實上或法律上之主張欠缺合理依據，法院認定屬於濫 訴者，僅得以判決駁回之','當事人起訴屬於濫訴時，法院亦得斟酌情形處訴訟代理人罰鍰','濫訴禁止是基於維護司法公益之目的，被告支付之律師酬金，不得列為訴訟費用之一部','濫訴之處罰，僅限於第一審，不適用上訴審程序','民事訴訟法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],8,8,'parsed','pending_manual_review',null,true),
('112-3301-056','112-3301',56,'single_choice','16 歲且未婚之甲懷胎6 月，服用未經我國認許成立之某外商A 公司所生產之藥品後身體不適，經就 醫後發現腹中胎兒乙的生長有遲滯現象，甲認為係因服用A 公司生產藥品所導致，以自己及乙為原 告，起訴主張自己及乙之身體健康均受損害為由，向A 公司請求損害賠償。下列敘述，何者正確？','乙不具有當事人能力，法院應以裁定駁回乙部分之訴','A 公司未經我國認許成立，雖在臺灣設有代表人及營業所，就此訴訟仍不具當事人能力','甲就此損害賠償訴訟有訴訟能力','甲於訴訟審理中產下乙，但為死產，法院應以裁定駁回乙部分之訴','民事訴訟法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],8,8,'parsed','pending_manual_review',null,true),
('112-3301-057','112-3301',57,'single_choice','關於訴訟程序停止，下列敘述，何者錯誤？','兩造合意停止訴訟程序後，經原告聲明續行訴訟程序，得再一次合意停止訴訟程序，於停止期間復 聲明續行訴訟程序後，即不得再合意停止，若再次陳明合意停止訴訟程序，不生合意停止訴訟程序 之效力','原告不服第一審判決提起上訴，兩造於第二審法院無正當理由遲誤言詞辯論期日，除別有規定外， 視為合意停止訴訟程序，如兩造於4 個月內均不續行訴訟者，即視為撤回上訴','原告無正當理由於第一審言詞辯論期日未到場，被告到場陳明拒絕辯論，視為合意停止訴訟程序。 第一審法院認為必要乃依職權續行訴訟，如原告無正當理由仍遲誤言詞辯論期日不到場，被告雖到 場仍拒絕辯論者，即再次視為合意停止訴訟程序，如於4 個月內不續行訴訟者，即視為撤回其訴','第一審法院之審判長命當事人預納支出必要訴訟行為之費用，因當事人不預納費用致訴訟無從進 行，經定期通知他造墊支亦不為墊支者，視為合意停止訴訟程序，當事人逾4 個月未預納或墊支者， 視為撤回其訴','民事訴訟法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],8,8,'parsed','pending_manual_review',null,true),
('112-3301-058','112-3301',58,'single_choice','訴訟繫屬中為訴訟標的之法律關係已由被告移轉至第三人時，關於法院之處置，下列敘述，何者錯誤？','於第三人承受訴訟前，訴訟程序當然停止','第三人經兩造同意，得聲請代被告承當訴訟','如原告不同意第三人承當訴訟，被告或第三人均得聲請法院以裁定許可之','在第三人未參加或承當訴訟，及當事人未對其為訴訟告知時，法院知悉該項移轉，應即以書面將訴 訟繫屬之事實通知第三人','民事訴訟法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],9,9,'parsed','pending_manual_review',null,true),
('112-3301-059','112-3301',59,'single_choice','關於爭點整理程序，下列敘述，何者正確？','在準備程序要否由受命法官調查證據，可由合議庭裁量定之','在行合議審判之訴訟事件，不可在言詞辯論程序期日進行爭點整理','兩造當事人在起訴以前或訴訟外亦得成立簡化爭點之協議','受訴法院須先使兩造交換準備書狀，始得開始整理爭點','民事訴訟法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],9,9,'parsed','pending_manual_review',null,true),
('112-3301-060','112-3301',60,'single_choice','關於訴訟代理人，下列敘述，何者正確？','當事人委任律師為訴訟代理人，向法院提起民事訴訟，當事人於程序進行中死亡，訴訟程序當然停 止。該訴訟代理人在有繼承人承受訴訟前，不得為關於本案之訴訟行為','訴訟委任書若已記載「全權委任」字樣，該訴訟代理人即有和解、提起上訴及選任代理人之權限','由訴訟代理人終止訴訟委任，以書狀向法院陳報時即生效力，訴訟代理人嗣後再為之訴訟行為，均 不生效力','當事人雖不在法院之轄區內住居，但只要其受特別委任之訴訟代理人受送達之權限未受限制，且住 居法院所在地者，於計算法定期間時，即不得扣除在途期間','民事訴訟法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],9,9,'parsed','pending_manual_review',null,true),
('112-3301-061','112-3301',61,'single_choice','下列訴訟，何者得聲請法院裁定許可為訴訟繫屬事實之登記？','甲依買賣契約法律關係，訴請乙移轉A 地所有權','甲依所有物返還請求權，訴請乙返還無權占有之A 地','甲將A 地所有權移轉予乙後，以該物權移轉行為無效為由，依所有物妨害排除請求權，訴請乙塗銷 甲、乙間所有權移轉登記','甲以借名登記契約業經終止為由，訴請A 地登記名義人乙將A 地所有權移轉登記予甲','民事訴訟法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],9,9,'parsed','pending_manual_review',null,true),
('112-3301-062','112-3301',62,'single_choice','甲向乙公司購買之汽車有諸多瑕疵，在乙開設於A 地方法院管轄區域之保養廠維修多次未見改善， 甲擬向合意管轄之B 地方法院起訴請求減少價金。下列敘述，何者正確？','甲得於起訴前向本案訴訟管轄法院B 地方法院聲請保全證據，留置前述保養廠維修紀錄','法院駁回甲保全證據之聲請時，甲不得聲明不服','法院准許甲保全證據之聲請時，相對人乙得聲明不服','甲如於保全證據程序終結後逾30 日未對乙起訴，乙得向法院聲請裁定解除維修紀錄之留置','民事訴訟法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],9,9,'parsed','pending_manual_review',null,true),
('112-3301-063','112-3301',63,'single_choice','甲訴請判決命被告乙將A 地所有權移轉登記予甲，陳稱：某日，甲向乙購買A 地，約定價金為新臺 幣（下同）500 萬元，已付其中400 萬元，乙卻拒不辦理過戶，為此起訴等語。對此，乙請求判決駁 回甲之訴，抗辯稱：乙雖有出賣A 地之事，但甲尚未付清積欠之價金100 萬元云云。下列敘述，何者 錯誤？','在本訴訟，受訴法院在認為兩造之主張均屬可採時，應在判決主文寫明：乙應於甲給付其100 萬元 之同時，將A 地所有權移轉登記予甲等旨，而不得判決甲之請求為全部無理由','在受訴法院採用上述選項所示判決主文為判決並經確定時，乙得據此判決為執行名義對甲強 制執行','在本訴訟中，乙就其對甲之100 萬元價金債權，如不知其得提起反訴時，受訴法院應加以闡明','在訴訟中，乙抗辯系爭買賣契約已經解除，就甲所積欠之價金，得併為訴之聲明：如法院認為A 地 所有權移轉登記請求為有理由時，甲應給付乙100 萬元','民事訴訟法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],9,9,'parsed','pending_manual_review',null,true),
('112-3301-064','112-3301',64,'single_choice','甲訴請乙返還A 車，主張該車為甲所有，被乙無權占有，依所有物返還請求權為請求。下列敘述，何 者錯誤？','本件訴訟之原告已經表明訴訟標的為甲對乙之所有物返還請求權','如乙否認甲就A 車之所有權存在，則甲就其有A 車所有權之該當要件事實，應先具體陳述，然後 就乙所否認之具體事實，甲應負證據提出責任','在乙承認甲就A 車之所有權存在時，受訴法院不得據以認定甲有A 車所有權，而須再闡明甲就該 權利發生之要件事實為具體陳述並提出證據','在乙抗辯其就A 車對甲有租賃權，而甲否認乙有租賃權時，則乙就該租賃權發生之要件事實應為 具體陳述，然後就甲所否認之事實負證據提出責任','民事訴訟法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],10,10,'parsed','pending_manual_review',null,true),
('112-3301-065','112-3301',65,'single_choice','甲以其所有之A 地遭乙無權占有為由，依民法第767 條第1 項規定，起訴請求乙返還A 地（下稱前 訴訟），經法院於民國110 年12 月1 日判決（下稱系爭判決）甲勝訴，乙未上訴而確定。下列敘述， 何者正確？','甲於111 年2 月15 日，以乙於系爭判決言詞辯論終結前已無權占有A 地3 年為由，依民法第179 條規定，請求乙給付相當於租金之不當得利，已為系爭判決之既判力效力所及','乙於系爭判決確定後，起訴請求確認甲非A 地之所有權人，法院應依民事訴訟法第249 條第1 項 第7 款規定駁回該訴','乙以其於前訴訟事實審言詞辯論終結後與甲訂立租約，對甲起訴請求確認其就A 地之租賃權存在， 法院不受前訴訟系爭判決所認定乙乃無權占有A 地之拘束，得另為認定乙有租賃權','甲於111 年1 月2 日將A 地所有權移轉登記於丙，丙不得持系爭判決對乙強制執行返還A 地','民事訴訟法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],10,10,'parsed','pending_manual_review',null,true),
('112-3301-066','112-3301',66,'single_choice','關於法院之調解，下列敘述，何者正確？','法院之調解與訴訟上和解由於都是在法院進行，所以均僅由法官居中促成','就調解事件有利害關係之第三人，經法官之許可，得參加調解程序','於第二審時，僅能為訴訟上和解，不能試行法院之調解','醫療糾紛因當事人間並無一定情誼，且爭議很大，通常難能成立和解，故非為起訴前應經法院調解 之事件','民事訴訟法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],10,10,'parsed','pending_manual_review',null,true),
('112-3301-067','112-3301',67,'single_choice','關於簡化判決書之規定，下列敘述，何者錯誤？','簡易程序判決書之事實及理由，得合併記載其要領或引用當事人書狀、筆錄或其他文書，必要時得 以之作為附件','簡易程序中，本於當事人對訴訟標的之捨棄或認諾者，判決書得僅記載主文','簡易庭法官得於宣示判決時，命將判決主文及事實、理由之要領，記載於言詞辯論筆錄，不另作判 決書','小額程序之判決書，得僅記載主文，均無加記理由要領之必要','民事訴訟法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],10,10,'parsed','pending_manual_review',null,true),
('112-3301-068','112-3301',68,'single_choice','關於小額訴訟事件，下列何者，不屬法院得逕依一切情況認定事實為判決而不調查證據之情形？','經兩造同意者','該事件依法應行調解程序，被告經於調解期日5 日前受合法通知未到場，法院依職權由原告一造辯 論而為判決者','原告聲請調查之證據方法僅有詢問住在智利之證人1 名，因該證人臥病行動不便，需支出日費、旅 費新臺幣（下同）23 萬元','原告主張被告應支付房屋鄰損修繕費7 萬元，原告除聲請鑑定外，陳明無其他證據方法，經法院選 任臺北市建築師公會鑑定，該公會覆知鑑定需費時10 個月始能完成，鑑定費用為35 萬元','民事訴訟法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],10,10,'parsed','pending_manual_review',null,true),
('112-3301-069','112-3301',69,'single_choice','第一審法院為原告一部勝訴、一部敗訴之判決，原告就其敗訴部分提起第二審上訴。關於附帶上訴， 下列敘述，何者錯誤？','上訴合法者，被上訴人縱曾捨棄上訴權，仍可在言詞辯論終結前，提起附帶上訴','經第三審法院發回第二審法院，被上訴人在更審期間，不得提起附帶上訴','上訴因不合法經駁回，如附帶上訴已具備上訴之要件，不失其效力','附帶上訴如已具備上訴之要件，不因原告合法撤回起訴而失其效力','民事訴訟法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],10,10,'parsed','pending_manual_review',null,true),
('112-3301-070','112-3301',70,'single_choice','甲以乙為被告提起請求返還借款之訴訟，乙自認有收受甲交付之款項，但抗辯該款項並非基於消費借 貸關係，甲無借款返還請求權，若前開抗辯無理由，則以對甲之同額債權予以抵銷。第一審判決認甲 對乙有借款返還請求權，但乙所為抵銷抗辯可採，而駁回甲之訴。甲、乙均不服，各自提起第二審上 訴。下列敘述，何者正確？','甲於上訴狀內僅記載不服原判決，但未表明應如何廢棄或變更之聲明者，原第一審法院無須命補正， 應逕認上訴不合法，以裁定駁回上訴','甲未依法繳納上訴裁判費，經原第一審法院定期命甲補正，甲未補正，卷宗送至第二審法院後，審 判長仍應再定期命補正，於甲逾期未補正時，法院始得裁定駁回甲之上訴','乙因債權經抵銷始獲勝訴判決，仍屬受不利判決，有上訴利益','乙未於上訴狀內表明上訴理由，第二審法院審判長得定相當期間命乙提出理由書，如乙逾期未提出， 審判長得命乙以書狀說明理由，逾期未說明者，第二審法院應裁定駁回乙之上訴','民事訴訟法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],11,11,'parsed','pending_manual_review',null,true),
('112-3301-071','112-3301',71,'single_choice','關於上訴第三審，下列敘述，何者錯誤？','對第一審判決未提起上訴或附帶上訴之當事人，於第二審判決駁回上訴時，不得上訴','不服簡易訴訟程序之第二審判決，不論金額為何，均不得向最高法院提起上訴','當事人委任律師對第二審判決聲明上訴後20 日內，未提出上訴理由書者，原第二審法院無庸命其 補正，以裁定駁回之','上訴第三審，不得再為訴之變更或追加','民事訴訟法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],11,11,'parsed','pending_manual_review',null,true),
('112-3301-072','112-3301',72,'single_choice','關於第二審程序，下列敘述，何者正確？','採嚴格續審制，故上訴後除第一審判決違反法令外，當事人不得提出新攻擊或防禦方法','當事人僅能於言詞辯論期日撤回上訴','第一審訴訟程序有重大瑕疵，為維持審級利益之必要，第二審法院得廢棄發回原法院','上訴狀未表明上訴理由時，經第二審法院通知補正仍未補正，得逕以裁定駁回上訴','民事訴訟法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],11,11,'parsed','pending_manual_review',null,true),
('112-3301-073','112-3301',73,'single_choice','當事人對第二審法院依通常訴訟程序所為終局判決不服，提起第三審上訴，下列何者作為上訴理由， 須經第三審法院之許可？','判決斟酌A 書證之事實認定，違背證據法則','判決理由先認上訴人占有B 地是基於租賃關係為有權占有，復謂被上訴人基於所有物返還請求權 請求上訴人返還B 地有理由，前後矛盾','參與辯論之法官為甲、乙、丙，參與判決之法官為甲、乙、丁','上訴人係未成年人，在未經上訴人之法定代理人合法代理之情形下，第二審法院逕為本案判決','民事訴訟法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],11,11,'parsed','pending_manual_review',null,true),
('112-3301-074','112-3301',74,'single_choice','關於再審之訴或聲請再審，下列敘述，何者正確？','當事人於再審書狀中表明依民事訴訟法第496 條第1 項第1 款，提起再審之訴，應認已合法表明再 審理由','當事人於判決確定後第10 日，發現當日出刊之雜誌所載內容，恰可援為證據，不得據以為再審事由','當事人於民國110 年1 月20 日收受第三審法院判決，經請教律師後，於110 年3 月1 日知悉該確 定判決適用法規錯誤，其旋於翌日依民事訴訟法第496 條第1 項第1 款規定，對該確定判決提起再 審之訴，依最高法院裁判見解，並未逾不變期間','當事人就確定判決於民事訴訟法第500 條所定之再審不變期間末日，依民事訴訟法第496 條第1 項 第13 款提起再審之訴，即已合法提起再審，為求訴訟經濟、紛爭一次解決，依最高法院裁判見解， 可於訴訟進行中，併主張同條項第1 款之再審事由','民事訴訟法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],11,11,'parsed','pending_manual_review',null,true),
('112-3301-075','112-3301',75,'single_choice','關於民事訴訟之抗告，下列敘述，何者正確？','原裁定法院接獲當事人之抗告狀後，認抗告為有理由，可自行撤銷或變更原裁定','原裁定法院誤認抗告未逾期，將該抗告事件送交抗告法院，抗告法院應將該抗告事件退由原裁定法 院處理，不得逕為駁回抗告之裁定','當事人聲請保全證據，經原法院裁定駁回，當事人於收受該裁定10 日內未對之提起抗告，僅聲明 異議，應由原裁定法院以不合法裁定駁回該異議而結案','合法之抗告得停止原裁定之效力','民事訴訟法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],11,11,'parsed','pending_manual_review',null,true),
('112-3301-076','112-3301',76,'single_choice','下列何者，不得單獨聲請？','假執行','假處分','定暫時狀態處分','假扣押','民事訴訟法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],12,12,'parsed','pending_manual_review',null,true),
('112-3301-077','112-3301',77,'single_choice','丁在某銀行之帳戶內有新臺幣（下同）200 萬元存款，於其死亡後，繼承人甲列乙及丙為被告，起訴 請求法院裁判分割遺產，並主張乙帳戶內有300 萬元存款亦屬丁所有，應併列入遺產分割範圍，由繼 承人甲、乙及丙繼承等語（下稱本案請求）。下列敘述，何者錯誤？','關於如何分割遺產，雖法院裁判時不受甲主張之分割方法所拘束，乙或丙仍得提出遺產分割方案供 法院斟酌','在兩造就「乙帳戶內300 萬元存款為遺產」之事實有爭執時，甲應提出證據予以證明','乙、丙對甲之繼承權有爭執時，法院應曉諭原告或被告得併就繼承權存否請求裁判','受訴法院不得依職權將本案請求移付調解，當事人在調解程序亦不得合意聲請法院就本案請求為 裁定','民事訴訟法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],12,12,'parsed','pending_manual_review',null,true),
('112-3301-078','112-3301',78,'single_choice','甲夫、乙妻結婚後1 年，乙與丙男發生性關係，嗣產下一子丁。未成年之丁知悉此事後，欲否認其與 甲之父子關係。下列敘述，何者錯誤？','丁得向自己住所地之法院提起否認推定生父之訴','丁提起否認推定生父之訴，僅列甲為被告即足，無庸以乙為共同被告','於丁所提否認推定生父之訴，法院不應將訴訟事件及進行程度通知丙','於丁所提否認推定生父之訴，就甲及丁間血緣關係存否之爭執，法院認有必要時，得依職權命雙方 接受醫學上之檢驗','民事訴訟法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],12,12,'parsed','pending_manual_review',null,true),
('112-3301-079','112-3301',79,'single_choice','甲、乙係夫妻，曾以書面約定將坐落臺南市之A 屋登記為甲之名義所有，如將來因該財產涉訟，同意 由起訴時甲之住所地法院管轄。嗣甲、乙因感情破裂分居，甲住高雄市，乙住臺南市，但甲、乙二人 平日均在彰化市上班、生活。甲列乙為被告，向臺灣臺南地方法院（下稱臺南地院）民事庭起訴請求 確認甲就A 屋之所有權存在（前訴訟）。又，乙列甲為被告另向臺灣高雄少年及家事法院（下稱高雄 少家法院）起訴，請求判決准兩造離婚，並將夫妻財產酌予分配（後訴訟）。關於有無審判權或管轄 權之處理，下列敘述，何者正確？','因臺南地院就前訴訟有專屬管轄權，所以兩造一律不得合意聲請法院將前訴訟移送高雄少家法院為 合併審判','在高雄少家法院審理後訴訟之程序上，兩造爭執A 屋是否為兩造婚後所取得之財產，此時兩造得 合意聲請臺南地院將前訴訟移送於高雄少家法院為合併審判','在當事人尚未提起前訴訟及後訴訟以前，就該二訴訟，兩造不得以書面合意由臺灣彰化地方法院家 事法庭審判','臺南地院應依職權將前訴訟移送於受理後訴訟之高雄少家法院','民事訴訟法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],12,12,'parsed','pending_manual_review',null,true),
('112-3301-080','112-3301',80,'single_choice','關於婚姻事件程序，下列敘述，何者錯誤？','夫妻持續1 年以上在中華民國有共同之居所，縱其二人均非中華民國國民，由夫或妻所提離婚事件， 中華民國法院仍有審判管轄權','婚姻事件之夫或妻受監護宣告者，除能證明其有意思能力外，應由其監護人代為訴訟行為','離婚之訴，夫或妻於事實審言詞辯論終結前死亡者，因已無對立當事人，法院應以判決駁回原告之訴','撤銷婚姻之訴，原告於判決確定前死亡者，有權提起同一訴訟之他人，得於知悉原告死亡時起3 個 月內聲明承受訴訟，但原告死亡後已逾1 年者，即不得再承受訴訟','民事訴訟法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],12,12,'parsed','pending_manual_review',null,true),
('112-4301-001','112-4301',1,'single_choice','A 有限公司有甲、乙及丙3 位股東，各出資新臺幣100 萬元，由甲擔任董事，下列關於乙、丙監督甲 業務執行之敘述，何者正確？','乙、丙得隨時向執行業務之股東質詢公司營業情形，但應共同為之','乙、丙得隨時查閱公司之財產文件、帳簿、表冊，但應共同為之','若甲違反競業禁止規定，自其所得產生後未逾1 年者，乙、丙得以經表決權過半數之決議，將甲為 自己或他人所為行為之所得，作為公司之所得','若甲執行業務，有重大損害公司之行為或違反法令或章程之重大事項，乙或丙得訴請法院裁判解任之','公司法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],1,1,'parsed','pending_manual_review',null,true),
('112-4301-002','112-4301',2,'single_choice','從事科技業之A 股份有限公司（下稱A 公司）持有B 股份有限公司（下稱B 公司）全部已發行股份。 B 公司因融資需要，債權人要求其須提供一定擔保。A 公司董事長甲考量B 公司為A 公司全資子公 司，故以A 公司所有土地為B 公司設定抵押。查A 公司章程並未有得對外保證條款。則依司法實務 見解，前開設定抵押行為是否合法？','合法，因B 公司為A 公司全資之子公司，經濟上本為一整體','不合法，因A 公司所有土地依法不得設定抵押予他人','合法，因A 公司並非為保證人，不違反公司法規定','不合法，因A 公司章程未有得對外保證條款','公司法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],1,1,'parsed','pending_manual_review',null,true),
('112-4301-003','112-4301',3,'single_choice','甲為專門處理商事案件的律師，近來其客戶業績蓬勃發展，紛紛想轉換組織型態以因應公司資本與組 織之需求，甲身為A、B、C、D 四間公司之律師，就客戶需求之建議，下列敘述何者錯誤？','A 公司為有限公司，想轉換公司型態，甲建議A 公司必須取得股東表決權過半數之同意後可轉換 為股份有限公司，並應向公司的債權人分別通知及公告','B 公司為兩合公司，想轉換公司型態，甲建議B 公司取得三分之二以上股東之同意變更章程，將 該公司變更為有限公司或股份有限公司','C 公司為家族經營的股份有限公司，想轉換公司型態，甲建議該公司得經代表已發行股份總數三分 之二以上股東出席之股東會，以出席股東表決權過半數之同意，變更為閉鎖性股份有限公司','D 公司為閉鎖性股份有限公司，想轉換為一般股份有限公司，甲建議D 公司得經有代表已發行股 份總數三分之二以上股東出席之股東會，以出席股東表決權過半數之同意，即可為之','公司法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],1,1,'parsed','pending_manual_review',null,true),
('112-4301-004','112-4301',4,'single_choice','下列何者非屬公司負責人？','依公司法第173 條報經主管機關許可自行召集股東會之少數股東','依公司法第245 條聲請法院選派檢查公司業務帳目及財產情形之檢查人','有限公司之經理人但未兼任該公司董事','法院依公司法第208 條之1 選任之臨時管理人','公司法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],1,1,'parsed','pending_manual_review',null,true),
('112-4301-005','112-4301',5,'single_choice','A 有限公司於民國110 年初設立，原本無設立分公司之規劃，未於章程中記載分公司設立之相關事項。 於同年底，未先變更章程便於嘉義設立分公司，則設立分公司之效力如何？','無效','效力未定，須俟章程變更後始生效力','無對抗效力','有效','公司法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],1,1,'parsed','pending_manual_review',null,true),
('112-4301-006','112-4301',6,'single_choice','甲支持自己的一雙子女乙、丙創業，乙成立了非公開發行之A 股份有限公司（下稱A 公司），丙成立 了B 閉鎖性股份有限公司（下稱B 公司），甲對A、B 公司各出資一千萬元而取得A、B 公司的複數 表決權特別股，但為了避免子女缺乏商場經驗、輕率魯莽導致公司經營不善虧損連連，甲要求擔任A、 B 公司的監察人。下列敘述何者錯誤？','關於公司的董事選舉，A 公司之選舉只能採取累積投票制，B 公司得以章程排除累積投票制','關於公司監察人選舉，甲在B 公司之特別股擁有複數表決權，但在A 公司之特別股，其表決權與 普通股股東之表決權同','為了保障公司經營與股權穩定，A、B 公司均可發行限制轉讓之特別股予甲','為了節省公司經營成本，A、B 公司均得以章程允許股東會與董事會透過視訊或書面開會','公司法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],2,2,'parsed','pending_manual_review',null,true),
('112-4301-007','112-4301',7,'single_choice','股份有限公司之股東，欲請求公司監察人為公司對違法之董事提起訴訟，至少應具備下列何種資格？','繼續6 個月以上，持有已發行股份總數1%以上之股東','繼續6 個月以上，持有已發行股份總數3%以上之股東','繼續1 年以上，持有已發行股份總數1%以上之股東','繼續1 年以上，持有已發行股份總數3%以上之股東','公司法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],2,2,'parsed','pending_manual_review',null,true),
('112-4301-008','112-4301',8,'single_choice','關於公司法第172 條之1 的股東提案權，下列敘述何者正確？','股東提案權非股東之固有權，得以章程限制或免除','股東提案權為少數股東權，限持股百分之三以上之股東方可提案','只限股東常會，股東才享有提案權','董事會對於股東之提案，如不列入議案時，應於股東會後說明未列入之理由','公司法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],2,2,'parsed','pending_manual_review',null,true),
('112-4301-009','112-4301',9,'single_choice','A 公司持有B 公司已發行有表決權股份總數之百分之六十，A 公司及B 公司分別持有C 公司已發行 有表決權股份總數之百分之三十。甲雖持有C 公司已發行股份總數之百分之三，但全部皆為無表決權 股份。若A 公司基於對C 公司之控制力，促使C 公司以市價五成之價格賤賣其不動產給B 公司，且 未於該會計年度終了時對C 公司為適當補償，下列敘述何者錯誤？','A 公司及其負責人應就C 公司之損害負連帶賠償責任','B 公司於其所受利益限度內，就A 公司應負之損害賠償責任，應連帶負責','C 公司之債權人得以自己名義行使C 公司對A 公司及其負責人之求償權，請求對C 公司為給付','甲得以自己名義行使C 公司對A 公司及其負責人之求償權，請求對C 公司為給付','公司法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],2,2,'parsed','pending_manual_review',null,true),
('112-4301-010','112-4301',10,'single_choice','A 股份有限公司（下稱A 公司）為B 股份有限公司（下稱B 公司）百分之百持股之從屬公司。B 公 司擬以A 公司為存續公司，吸收合併C 股份有限公司（下稱C 公司），但此宗合併案受到B 公司股 東甲、C 公司股東乙反對。若此宗合併案通過後，甲、乙何人能主張股份收買請求權？','甲','乙','甲與乙皆可','甲與乙皆不可','公司法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],2,2,'parsed','pending_manual_review',null,true),
('112-4301-011','112-4301',11,'single_choice','A 股份有限公司（下稱A 公司）為上市公司，欲召開股東常會，下列何事項A 公司得以臨時動議提出？','董事甲欲擔任與A 公司營業範圍相同之競爭B 公司之董事長','A 公司欲增加其章程所定之股份總數','A 公司欲將年度應分派之股息以發行新股方式為之','A 公司欲以股東會決議之方式同意本次轉投資後，公司轉投資總額為實收股本百分之五十','公司法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],2,2,'parsed','pending_manual_review',null,true),
('112-4301-012','112-4301',12,'single_choice','A 股份有限公司（下稱A 公司）雖握有公司產品科技之重要專利，但是隨著科技推陳出新，舊有的技 術無法趕上時代，A 公司逐漸失去市場上的優勢，股價一落千丈。上個月A 公司突然發生債務無法清 償的財務危機，致公司岌岌可危而欲重整，關於重整的規定，下列敘述何者錯誤？','為了保障員工的權益，A 公司三分之二以上之受僱員工可以為公司聲請重整','公司負債過於龐大，繼續6 個月以上相當於公司已發行股份總數金額達百分之五之公司債權人可以 向法院聲請重整','一旦法院裁定重整，A 公司原有的股東會、董事、監察人所有職權都必須停止','法院裁定重整後，重整人應擬訂重整計畫，連同公司業務及財務報表，提請由股東與債權人組成的 重整關係人會議審查','公司法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],2,2,'parsed','pending_manual_review',null,true),
('112-4301-013','112-4301',13,'single_choice','非公開發行股票之A 公司，董事均由股東親自擔任，公司主要營運地點於海外，日常業務之經營則均 委由總經理決定。董事均事務繁忙，為求簡便，已修改章程允許公司董事會得採取書面會議。本次對 於法務經理之聘任案，公司欲採用書面會議決定，5 名董事中有3 名贊成採書面會議方式並表示同意 此一聘任案。其餘2 名董事不贊成書面會議方式並表示反對此一聘任案。下列敘述，何者正確？','本次會議合法，因章程已規定得採取書面會議','本次會議不合法，贊成採書面會議之董事人數不足法定成數','本次會議不合法，因未有三分之二以上董事贊成此一聘任案','本次會議合法，因已有過半數董事贊成此一聘任案','公司法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],3,3,'parsed','pending_manual_review',null,true),
('112-4301-014','112-4301',14,'single_choice','A 股份有限公司（下稱A 公司）董事甲，違法執行職務導致公司受損，股東會擬決議解任之。公司法 有關解任董事之規定，下列敘述何者錯誤？','A 公司股東會如欲通過解任董事甲之議案，其股東會應以特別決議為之','A 公司股東會如未通過解任董事甲之議案，股東乙欲提起解任董事之訴，至少須持有已發行股份總 數百分之三之股份','A 公司股東會如未通過解任董事甲之議案，符合持股條件之股東如欲訴請法院裁判解任甲，應於股 東會後30 日內為之','A 公司股東會如未通過解任董事甲之議案，監察人得隨時提起解任董事之訴','公司法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],3,3,'parsed','pending_manual_review',null,true),
('112-4301-015','112-4301',15,'single_choice','A 公司與B 公司均為非公開發行之股份有限公司，雙方均知悉有相互投資之事實。A 公司已發行股份 總數共3,000 萬股，B 公司已發行股份總數共1,500 萬股，均為有表決權股份。若A 公司持有B 公司 600 萬股，B 公司持有A 公司1,000 萬股，均非因盈餘或公積增資配股所得之股份，則A 公司於B 公 司股東會最多得行使表決權之股份數為多少？','500 萬股','300 萬股','200 萬股','0 股','公司法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],3,3,'parsed','pending_manual_review',null,true),
('112-4301-016','112-4301',16,'single_choice','甲以其房屋向A 產物保險股份有限公司（下稱A 公司）投保火災保險，並約定保險金額為新臺幣（下 同）1,000 萬元。其後甲屋發生火災以致房屋部分毀損，損失900 萬元，甲為避免損失進一步擴大， 支出必要費用720 萬元，該屋並經A 公司鑑價，其保險標的價值為1,500 萬元。下列敘述何者正確？','A 公司就甲所支出之必要費用720 萬元，應全額償還','A 公司就甲屋之損失應依其責任比例賠償600 萬元，但就甲為減輕損害所支出之必要費用720 萬 元應全額償還，共計1,320 萬元','A 公司就甲屋之損失應依其責任比例賠償600 萬元，就甲為減輕損失所支出之必要費用依其比例 償還480 萬元，然其給付金額以保險金額為上限，共計1,000 萬元','A 公司就甲屋之損失應依其責任比例賠償600 萬元，就甲為減輕損失所支出之必要費用依其比例 償還480 萬元，共計支付1,080 萬元','保險法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],3,3,'parsed','pending_manual_review',null,true),
('112-4301-017','112-4301',17,'single_choice','甲父以其未出嫁而同居一家之女兒乙為被保險人投保終身人壽保險，並指定甲為受益人。於保險有效 期間，乙結婚並與其配偶丙搬離娘家。數年後，乙死亡。下列敘述何者正確？','甲不得請求保險給付，因乙出嫁與其配偶丙成家後，保險契約效力即行終止','甲得請求保險給付，乙之出嫁並與配偶丙成家並不影響保險契約之效力，因人身保險僅在締結保險 契約時具有保險利益即可','甲不得請求保險給付，因乙出嫁與其配偶丙成家後，甲即喪失受益人資格，此時保險金為乙之遺產','甲得請求保險給付，乙雖出嫁與其配偶丙成家，但對甲仍負有扶養義務，故保險人應在乙之扶養義 務範圍內給付甲保險金','保險法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],3,3,'parsed','pending_manual_review',null,true),
('112-4301-018','112-4301',18,'single_choice','甲展售高價鑽錶一批，與乙簽訂保全服務契約，並向A 保險公司投保商業動產流動綜合保險。因乙之 過失，保全系統失效，致鑽錶失竊。A 保險公司於賠付保險金後，得否向乙主張代位權？','可，因甲對乙具有損害賠償請求權','可，但僅以甲對乙有侵權行為損害賠償請求權為限','不可，因甲對乙的請求權基礎係基於契約關係','不可，因甲對乙的請求權係基於侵權行為損害賠償請求權','保險法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],3,3,'parsed','pending_manual_review',null,true),
('112-4301-019','112-4301',19,'single_choice','A 保險公司欲投資不動產，依目前保險法之規定，下列敘述何者錯誤？','其投資總額，除自用不動產外，不得超過其資金百分之三十','購買之自用不動產總額不得超過其業主權益之總額','保險業對不動產之投資，以所投資不動產能即時利用為限，但不以立即有收益為必要','對不動產之取得及處分，應經合法之不動產鑑價機構評價','保險法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],4,4,'parsed','pending_manual_review',null,true),
('112-4301-020','112-4301',20,'single_choice','A 公司以其所有甲畫家之畫作向B 產物保險股份有限公司（下稱B 公司）投保藝術品保險，雙方約 定採定值方式投保，保險金額新臺幣（下同）100 萬元。保險期間因乙縱火導致該畫作焚毀無法修復， B 公司於給付保險金100 萬元後，即向乙代位求償，經鑑定後該畫作僅值90 萬元。試問：B 公司得 向乙代位求償之金額為何？','10 萬元','90 萬元','100 萬元','B 公司不得代位，因B 公司已從A 公司收取保險費','保險法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],4,4,'parsed','pending_manual_review',null,true),
('112-4301-021','112-4301',21,'single_choice','甲經體檢發現自身甲狀腺腫大，乃以自己為被保險人，指定其妻乙為受益人，投保死亡保險，但對要 保書之詢問隱匿此項檢查異常情況。然一年後甲發生重大車禍，不治死亡。乙向保險人請求保險金， 保險人發現甲於投保時不實說明，得否拒絕理賠？','保險人得拒絕理賠，但乙可主張自己善意不知情','保險人依保險法第64 條規定解除契約後即無須理賠','因甲之死亡與其違反據實說明義務間並無因果關係，保險人不得拒絕理賠，但得請求賠償因此所受 之損害','乙得證明甲之死亡並非基於其所隱匿之體況，保險人仍應給付保險金','保險法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],4,4,'parsed','pending_manual_review',null,true),
('112-4301-022','112-4301',22,'single_choice','A 醫院向B 保險公司投保醫院綜合責任險，保險金額每一事故新臺幣（下同）300 萬元。甲女就診期 間因施打麻醉劑休克死亡，A 醫院在B 保險公司人員參與下與甲女家屬達成600 萬元和解。嗣後，B 保險公司以參與和解當時其並未明示或默示同意和解金額為由，拒絕A 醫院之理賠申請。下列關於 本責任保險人和解參與權之敘述，何者正確？','參與權包括保險人之和解參加權及和解同意權二權利，亦即保險人未同意和解，保險人不受該和解 之拘束','參與權包括保險人之和解參加權及和解同意權二權利，亦即保險人未同意和解，保險人免除其理賠 責任','參與權僅包括和解參加權，不包括和解同意權，保險人一旦參與和解，保險人即應受和解效力之拘束','參與權僅包括和解參加權，不包括和解同意權，保險人參與和解，除有正當理由得拒絕和解條件或 其他除外不保理由外，保險人在保險金額範圍內應受和解之拘束','保險法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],4,4,'parsed','pending_manual_review',null,true),
('112-4301-023','112-4301',23,'single_choice','甲以其14 歲女兒乙為被保險人，向A 保險公司投保人壽保險，該契約效力為何？','效力未定，須待乙滿15 歲時契約方生效','契約無效','乙未滿15 歲，死亡險部分無效，其他部分若能單獨成立，則仍然有效','契約有效，但除喪葬費用之給付外，其餘死亡給付之約定於乙滿15 歲時始生效力','保險法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],4,4,'parsed','pending_manual_review',null,true),
('112-4301-024','112-4301',24,'single_choice','甲以自己為被保險人投保人壽保險，並指定其配偶乙為受益人，保險契約中有條款約定，變更受益人 須以書面申請並經保險公司同意且批註後始生效力。於保險期間，甲以書面申請變更受益人為其母校 A 大學，但在保險公司未批註後即死亡。依目前保險法令及通說見解，下列敘述，何者正確？','保險契約之受益人已變更為A 大學，故A 大學有保險給付請求權','因保險公司未完成批註，保險契約之受益人仍為乙，故乙有保險給付請求權','因A 大學與甲之間並無保險利益，故此變更受益人不生效力，保險契約之受益人仍為乙，故乙有保 險給付請求權','保險公司雖收受受益人變更申請書，但保險契約之受益人變更尚須保險人同意始生效力，故乙有保 險給付請求權','保險法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],4,4,'parsed','pending_manual_review',null,true),
('112-4301-025','112-4301',25,'single_choice','下列關於再保險之敘述，何者錯誤？','再保險依其性質應為責任保險','原保險契約與再保險契約得以條款約定，原保險契約之被保險人於保險人無法履行保險責任時，得 向再保險人請求','再保險人不得向原保險契約之要保人請求交付保險費','原保險契約得以條款約定，再保險不履行其給付義務時，保險人得拒絕或延遲其保險金給付義務','保險法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],5,5,'parsed','pending_manual_review',null,true),
('112-4301-026','112-4301',26,'single_choice','甲簽發金額新臺幣（下同）10 萬元，A 為付款人，一個月後到期之匯票予乙作為購買其二手車之部分 價金。後因家人反對購買二手車而解除契約，並賠償乙現金8 千元以彌補其損失。乙告知甲已將該票 銷毀，然事實上卻將該票空白背書轉讓予善意之丙，以償還其所積欠款項。丙隨後得知丁近日與朋友 共同創立公司，隨即又再將該票直接交付並贈與善意之丁，表示鼓勵年輕人創業。若該票到期不獲付 款，下列敘述何者正確？','丁得對甲及乙行使追索權','丁僅得對甲行使追索權，不得對乙行使追索權','丁僅得對乙行使追索權，不得對甲行使追索權','因丁為無償取得，故丁對甲及乙均不得行使追索權','票據法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],5,5,'parsed','pending_manual_review',null,true),
('112-4301-027','112-4301',27,'single_choice','依票據法第22 條規定，關於利益償還請求權之敘述，下列何者正確？','利益償還請求權人以最後之被背書人為限','匯票、本票之發票人及其保證人，支票之發票人、匯票之承兌人均為利益償還請求權之償還義務人','執票人得就其所受損害行使利益償還請求權','票據上之權利，係依票據法因時效或手續之欠缺而消滅時，執票人始得主張利益償還請求權','票據法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],5,5,'parsed','pending_manual_review',null,true),
('112-4301-028','112-4301',28,'single_choice','甲簽發一紙以A 為付款人之匯票予受款人乙，乙背書讓與丙，丙再背書讓與丁，丁則委任取款背書予 戊。當戊向A 付款提示而被拒付時，戊不得向下列何人主張票據責任？','甲','乙','丙','丁','票據法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],5,5,'parsed','pending_manual_review',null,true),
('112-4301-029','112-4301',29,'single_choice','甲簽發匯票一紙交付給乙，依序由乙、丙、丁記名背書，執票人戊之子己趁戊不注意時，將其好友丙 之簽名塗銷，若匯票於到期日不獲付款，戊可向下列何人行使追索權？','僅甲、乙','僅甲、乙、丁','僅甲、乙、丙、丁','僅甲、乙、己','票據法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],5,5,'parsed','pending_manual_review',null,true),
('112-4301-030','112-4301',30,'single_choice','甲簽發一張以A 為付款人之匯票交付予乙，乙除背書外並請求B 在票據上簽名為其保證，然後將票 據轉讓予丙，丙除背書外於該票記載在付款地的C 為預備付款人，然後將該票據轉讓予丁，丁於到期 日前向A 請求承兌遭拒，丁得對何人行使期前追索權？','甲、乙、丙、A、B','甲、乙、丙、B、C','甲、乙、丙、B','甲、乙、丙、C','票據法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],5,5,'parsed','pending_manual_review',null,true),
('112-4301-031','112-4301',31,'single_choice','房客甲所承租之房屋，大門門鎖損壞，向房東乙請求支付更換費用新臺幣1 萬元，乙不願支付。爭議 經調解後，乙勉為同意支付半價，惟刻意不肯支付現金，而開立3 個月期本票予甲，意圖刁難；甲以 乙之配偶丙須擔任票據保證人為條件，而答應接受本票。本票到期後，乙仍不願支付，甲依票據法及 司法實務，可如何救濟？','甲得向乙丙追索，並聲請法院裁定後強制執行乙丙財產','甲得逕向丙追索，並聲請法院裁定後強制執行丙財產','甲於向乙追索無效後，得向丙追索，並聲請法院裁定後強制執行丙財產','甲得向乙丙追索，追索無效後，得聲請法院裁定後強制執行乙財產','票據法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],5,5,'parsed','pending_manual_review',null,true),
('112-4301-032','112-4301',32,'single_choice','臺北市A 公司董事長甲簽發該公司以桃園市B 銀行為付款人之支票予乙，作為買賣價金，票載發票 日為105 年4 月1 日，其後乙再將該支票背書轉讓予丙，甲於105 年4 月10 日發現貨物有顯著瑕疵， 即通知乙解除買賣契約，並同時通知B 銀行撤銷付款之委託，丙於105 年4 月18 日向B 銀行提示未 獲付款，下列敘述，何者正確？','丙之付款提示未逾法定提示期間','如付款銀行B 拒絕付款，丙得對乙行使追索權','如付款銀行B 拒絕付款，丙喪失對甲的追索權','付款銀行B 不得付款','票據法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],6,6,'parsed','pending_manual_review',null,true),
('112-4301-033','112-4301',33,'single_choice','甲簽發劃有平行線支票一張予乙，乙背書轉讓予丙，丙再背書轉讓予丁時，丁要求丙將平行線撤銷， 依票據法規定，下列敘述何者正確？','該支票不得撤銷平行線','甲在平行線內簽章即可撤銷','乙在平行線內簽章即可撤銷','丙在平行線內簽章即可撤銷','票據法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],6,6,'parsed','pending_manual_review',null,true),
('112-4301-034','112-4301',34,'single_choice','甲簽發記名匯票一紙予乙，票面金額新臺幣100 萬元整，乙背書轉讓予丙，若丙背書轉讓予丁時，丙 於背書時所為之下列何項行為，將使丙之背書不生效力？','將乙之背書塗銷','記載戊為預備付款人','丙背書旁附記「丁應依契約履約，否則本背書無效」','丙背書旁註記「轉讓金額新臺幣80 萬元」','票據法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],6,6,'parsed','pending_manual_review',null,true),
('112-4301-035','112-4301',35,'single_choice','甲簽發一紙以民國105 年10 月1 日為到期日，並記載乙為受款人之本票，交付給乙後，乙又將該本 票交付轉讓給丙，丙擅自偽造乙之背書，並將到期日更改為同年9 月1 日後背書轉讓給善意的丁，丁 於同年9 月1 日向甲提示付款被拒，下列敘述，何者正確？','依該票據外觀，其背書連續，且因屆期未獲付款，故丁得持該票據對甲、乙及丙行使追索權','依該票據外觀，其背書連續，但乙得以背書被偽造為由對抗丁，不用負票據責任','因乙之背書是被偽造，該票據之背書不連續，故丁無法行使任何票據權利','因乙之背書是被偽造，該票據之背書不連續，但乙背書之偽造不影響其他真正簽名者之效力，故丁 僅得對丙行使追索權','票據法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],6,6,'parsed','pending_manual_review',null,true),
('112-4301-036','112-4301',36,'single_choice','股票上市之A 股份有限公司（下稱A 公司）董事長甲，知悉足以影響該公司股價之消息，於該消息公 開前，以新臺幣（下同）100 元買進該公司股份10,000 股，迄今尚未賣出，該消息公開後翌日，A 公司 股票收盤價為115 元，消息公開後10 個營業日A 公司股票平均收盤價為140 元，若甲之行為被法院認 定構成內線交易，依最高法院大法庭之見解，計算甲之內線交易犯罪所得之敘述，下列何者正確？','甲未賣出，故無犯罪所得','計算犯罪所得時，不應扣除證券交易稅及手續費','甲之犯罪所得採擬制所得法計算','若有該內線消息以外因素影響A 公司股價，應將該因素影響之股價自犯罪所得中扣除','證券交易法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],6,6,'parsed','pending_manual_review',null,true),
('112-4301-037','112-4301',37,'single_choice','A 上市公司（下稱A 公司）為激勵優秀員工，擬採行庫藏股制度，使員工經由取得股份，對公司產生 向心力，下列敘述何者合法？','得經董事會三分之二以上董事之出席及出席董事超過二分之一同意，向A 公司之大股東買回股份','A 公司買回股份之數量比例，不得超過該公司已發行股份總數百分之一','A 公司收買股份之總金額，不得逾法定盈餘公積','A 公司收買自己之股份轉讓於員工時，得限制員工在一定期間內不得轉讓。但其期間最長不得超過 2 年','證券交易法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],6,6,'parsed','pending_manual_review',null,true),
('112-4301-038','112-4301',38,'single_choice','A 上市公司（下稱A 公司）近期以私募股份之方式，籌措公司投資所需之資金。甲為此次A 公司私 募有價證券之購買人。依證券交易法之規定，下列敘述何者錯誤？','此次有價證券私募應經股東會通過，且公司得於該股東會決議之日起2 年內，分次辦理','此次有價證券私募，該公司之員工及原股東並無優先認購權','A 公司只要在私募有價證券之價款繳納完成日起15 日內，檢附相關書件，報請主管機關備查即可， 無須事先向主管機關申報','若甲持有該私募有價證券尚未滿3 年，得以私人間之直接讓受，其數量不超過該證券一個交易單位， 前後2 次之讓受行為，相隔不少於3 個月之方式賣出','證券交易法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],7,7,'parsed','pending_manual_review',null,true),
('112-4301-039','112-4301',39,'single_choice','關於證券交易法規範之對象，下列敘述何者錯誤？','募集設立之公司在設立登記前，發起人不負發行人責任','外國公司係以營利為目的，依照外國法律組織登記之公司','公司制證券交易所之組織，以股份有限公司為限','除兼營之金融機構外，證券商須為股份有限公司','證券交易法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],7,7,'parsed','pending_manual_review',null,true),
('112-4301-040','112-4301',40,'single_choice','A 公司為一家從事汽車輪胎生產的上市公司，該公司設有甲、乙、丙、丁、戊5 名董事。依證券交易 法之規定，下列敘述何者錯誤？','公開發行公司董事會之董事人數不得少於5 人，故A 公司不得以章程降低董事人數','除經主管機關核准者外，甲、乙、丙、丁、戊5 名董事間應有超過半數之席次，不得具有配偶或三 親等以內之親屬關係','法人為A 公司之股東時，除經主管機關核准者外，不得由其代表人同時當選或擔任公司之董事及 監察人','若甲、乙、丙、丁、戊5 人中有2 人解任，則A 公司應自事實發生之日起60 日內，召開股東臨時 會補選之','證券交易法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],7,7,'parsed','pending_manual_review',null,true),
('112-4301-041','112-4301',41,'single_choice','A 上市公司今年第一季財務報告，因隱匿重要內容而有不實。關於財報不實責任之敘述，下列何者正確？','總經理甲故意違法，其應依其責任比例負賠償責任','董事長乙如能證明已盡相當注意，且有正當理由可合理確信其內容無隱匿情事者，免負賠償責任','財務報告之核閱會計師丙若不能證明自己已經合理調查，並有正當理由確信其核閱意見為真實者， 即應負賠償責任','請求賠償之原告須能證明在本財務報告簽章之職員丁有不正當或過失行為，方可要求丁負損害賠償 責任','證券交易法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],7,7,'parsed','pending_manual_review',null,true),
('112-4301-042','112-4301',42,'single_choice','A 上市公司之某次審計委員會中，下列議案均未獲審計委員會全體成員二分之一以上同意，下列何項 議案不得由全體董事三分之二以上同意行之？','經董事長、經理人、會計主管簽名或蓋章之年度財務報告案','財務主管甲之任命案','簽證會計師乙之委任案','重大之資產或衍生性商品交易案','證券交易法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],7,7,'parsed','pending_manual_review',null,true),
('112-4301-043','112-4301',43,'single_choice','我國證券市場發展日益興盛，營運多樣之證券商居功不少，而各種類型證券商所面對的管制亦有不同， 依照證券交易法，下列敘述何者錯誤？','證券承銷商辦理有價證券之承銷','證券經紀商辦理有價證券買賣之行紀、居間、代理、承銷','證券自營商辦理有價證券之自行買賣','證券交易法下證券商可以區分為證券承銷商、證券自營商、證券經紀商等三種','證券交易法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],7,7,'parsed','pending_manual_review',null,true),
('112-4301-044','112-4301',44,'single_choice','A 上市公司（下稱A 公司）為了擴大公司競爭力、發展垂直經濟，而B 上市公司（下稱B 公司），具 有良好體質與市場潛力，因此A 公司擬針對B 公司進行公開收購，但在過程中，因為發生一些情況， 需要改變公開收購條件，依證券交易法之規定，下列何者改變條件原則上屬於合法？','調降公開收購價格','降低預定公開收購有價證券數量','延長公開收購期間','縮短公開收購期間','證券交易法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],7,7,'parsed','pending_manual_review',null,true),
('112-4301-045','112-4301',45,'single_choice','A 公司為一家從事乳品販售之上市公司，該公司設有甲、乙、丙、丁、戊、己、庚、辛、壬9 名董事， 其中甲、乙、丙、丁、戊5 人為獨立董事。A 公司並設有審計委員會。依證券交易法之規定，下列敘 述何者正確？','A 公司得由甲、乙、丙3 名獨立董事組成審計委員會','A 公司審計委員會成員中至少1 人應具備會計或財務專長','A 公司董事會不得變更審計委員會之決議','A 公司審計委員會成員對其職權所有事項，均得各自獨立行使','證券交易法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],8,8,'parsed','pending_manual_review',null,true)
